const guideArticlesUnsorted: GuideArticle[] = [
  {
    id: 'find-your-way', category: 'start', image: 'tools.png', text: {
      ru: ['Где найти нужную функцию', 'Библиотека и коллекции доступны в боковой панели. Остальные действия открываются там, где они нужны.', 'На экране библиотеки нажмите «+», чтобы добавить файлы, найти издание в интернете или восстановить копию. Меню с тремя точками ведёт к программам, очереди импорта и инструментам.', 'В «Инструментах» собраны занятия, аудио, перенос пометок и умные коллекции. Шестерёнка открывает настройки, резервные копии и справку. Состав некоторых инструментов зависит от доступных возможностей приложения.'],
      en: ['Find your way around', 'Library and Collections are in the side rail. Other actions appear where you need them.', 'On the Library screen, press + to add files, find an edition online or restore a backup. The three-dot menu opens Programmes, the import inbox and Tools.', 'Tools groups practice, audio, mark transfer and smart collections. The gear opens Settings, backups and Help. Some tools appear only when their feature is available.'],
      de: ['Funktionen finden', 'Bibliothek und Sammlungen stehen in der Seitenleiste. Weitere Aktionen erscheinen am passenden Ort.', 'Tippen Sie in der Bibliothek auf +, um Dateien hinzuzufügen, online eine Ausgabe zu suchen oder eine Sicherung wiederherzustellen. Das Menü mit drei Punkten öffnet Programme, Import und Werkzeuge.', 'Unter Werkzeuge finden Sie Üben, Audio, Markierungsübertragung und intelligente Sammlungen. Das Zahnrad führt zu Einstellungen, Sicherungen und Hilfe. Manche Werkzeuge erscheinen nur, wenn die Funktion verfügbar ist.'],
      it: ['Trovare le funzioni', 'Biblioteca e Raccolte sono nella barra laterale. Le altre azioni compaiono nel contesto giusto.', 'Nella Biblioteca tocca + per aggiungere file, cercare un’edizione online o ripristinare un backup. Il menu con tre punti apre Programmi, importazione e Strumenti.', 'Strumenti riunisce studio, audio, trasferimento dei segni e raccolte intelligenti. L’ingranaggio apre Impostazioni, backup e Aiuto. Alcuni strumenti compaiono solo se la funzione è disponibile.'],
      es: ['Encontrar las funciones', 'Biblioteca y Colecciones están en la barra lateral. Las demás acciones aparecen donde se usan.', 'En Biblioteca pulsa + para añadir archivos, buscar una edición en línea o restaurar una copia. El menú de tres puntos abre Programas, importación y Herramientas.', 'Herramientas agrupa práctica, audio, transferencia de marcas y colecciones inteligentes. El engranaje abre Ajustes, copias y Ayuda. Algunas herramientas solo aparecen cuando su función está disponible.'],
      pt: ['Encontrar as funções', 'Biblioteca e Coleções ficam na barra lateral. As outras ações surgem no contexto certo.', 'Na Biblioteca prima + para adicionar ficheiros, procurar uma edição online ou repor uma cópia. O menu de três pontos abre Programas, importação e Ferramentas.', 'Ferramentas reúne estudo, áudio, transferência de marcas e coleções inteligentes. A roda dentada abre Definições, cópias e Ajuda. Algumas ferramentas só aparecem quando a função está disponível.'],
      uk: ['Де знайти потрібну функцію', 'Бібліотека й колекції є на бічній панелі. Інші дії з’являються там, де вони потрібні.', 'На екрані бібліотеки натисніть «+», щоб додати файли, знайти видання в інтернеті чи відновити копію. Меню з трьома крапками відкриває програми, імпорт та інструменти.', 'В «Інструментах» зібрано заняття, аудіо, перенесення поміток і розумні колекції. Шестерня відкриває налаштування, резервні копії й довідку. Деякі інструменти видно лише тоді, коли функція доступна.'],
      fr: ['Trouver une fonction', 'Bibliothèque et Collections sont dans la barre latérale. Les autres actions apparaissent dans leur contexte.', 'Dans Bibliothèque, appuyez sur + pour ajouter des fichiers, chercher une édition en ligne ou restaurer une sauvegarde. Le menu à trois points ouvre Programmes, l’import et Outils.', 'Outils regroupe travail, audio, transfert des marques et collections intelligentes. La roue dentée ouvre Réglages, sauvegardes et Aide. Certains outils n’apparaissent que si leur fonction est disponible.'],
      pl: ['Gdzie znaleźć funkcje', 'Biblioteka i Kolekcje są na pasku bocznym. Pozostałe działania pojawiają się tam, gdzie są potrzebne.', 'W Bibliotece naciśnij +, aby dodać pliki, znaleźć wydanie online lub przywrócić kopię. Menu z trzema kropkami otwiera Programy, import i Narzędzia.', 'Narzędzia grupują ćwiczenia, audio, przenoszenie oznaczeń i inteligentne kolekcje. Koło zębate otwiera Ustawienia, kopie i Pomoc. Niektóre narzędzia pojawiają się tylko wtedy, gdy funkcja jest dostępna.'],
    },
  },
  {
    id: 'first-scores', category: 'start', image: 'add.png', text: {
      ru: ['Добавить первые ноты', 'Личная библиотека начинается пустой: результаты интернет-поиска не появляются в ней сами.', 'Откройте «Добавить ноты» и выберите файлы или папку через системное окно Android. Можно выбрать несколько PDF; также поддерживаются JPEG, PNG, статический WebP и узкий профиль чёрно-белого Classic TIFF Group 4.', 'Просмотрите список перед импортом. Приложение сохраняет проверенную личную копию и не меняет внешний оригинал. Неуверенные названия и сведения можно исправить после добавления.'],
      en: ['Add your first scores', 'A new personal library is empty; online search results are never added automatically.', 'Open Add scores and choose files or a folder in the Android file picker. You can select several PDFs; JPEG, PNG, static WebP and a narrow black-and-white Classic TIFF Group 4 profile are also supported.', 'Review the selection before importing. The app keeps a verified private copy without changing the external original. You can correct uncertain titles and details afterwards.'],
      de: ['Erste Noten hinzufügen', 'Eine neue persönliche Bibliothek ist leer; Online-Ergebnisse werden nicht automatisch aufgenommen.', 'Öffnen Sie „Noten hinzufügen“ und wählen Sie Dateien oder einen Ordner im Android-Dateidialog. Mehrere PDFs sowie JPEG, PNG, statisches WebP und ein begrenztes Schwarzweiß-TIFF-Group-4-Profil werden unterstützt.', 'Prüfen Sie die Auswahl. Die App speichert eine geprüfte Kopie, ohne das externe Original zu verändern. Unsichere Angaben lassen sich danach korrigieren.'],
      it: ['Aggiungere i primi spartiti', 'Una nuova biblioteca personale è vuota; i risultati online non vi entrano da soli.', 'Apri Aggiungi spartiti e scegli file o una cartella dal selettore Android. Puoi scegliere più PDF; sono supportati anche JPEG, PNG, WebP statico e un profilo TIFF Group 4 monocromatico limitato.', 'Controlla la selezione. L’app salva una copia verificata senza modificare l’originale esterno. I dati incerti si possono correggere dopo.'],
      es: ['Añadir las primeras partituras', 'Una biblioteca nueva está vacía; los resultados en línea no se añaden solos.', 'Abre Añadir partituras y elige archivos o una carpeta con el selector de Android. Puedes elegir varios PDF; también se admiten JPEG, PNG, WebP estático y un perfil TIFF Group 4 monocromo limitado.', 'Revisa la selección. La app guarda una copia verificada sin modificar el original externo. Después puedes corregir los datos inciertos.'],
      pt: ['Adicionar as primeiras partituras', 'Uma biblioteca nova começa vazia; os resultados online não são adicionados automaticamente.', 'Abra Adicionar partituras e escolha ficheiros ou uma pasta no seletor Android. Pode escolher vários PDFs; JPEG, PNG, WebP estático e um perfil TIFF Group 4 monocromático limitado também são suportados.', 'Reveja a seleção. A aplicação guarda uma cópia verificada sem alterar o original externo. Pode corrigir os dados incertos depois.'],
      uk: ['Додати перші ноти', 'Нова особиста бібліотека порожня; результати пошуку в інтернеті не додаються автоматично.', 'Відкрийте «Додати ноти» й виберіть файли або папку через системний вибір Android. Підтримуються кілька PDF, JPEG, PNG, статичний WebP та обмежений чорно-білий TIFF Group 4.', 'Перевірте вибір. Застосунок зберігає перевірену копію, не змінюючи зовнішній оригінал. Непевні відомості можна виправити пізніше.'],
      fr: ['Ajouter ses premières partitions', 'Une nouvelle bibliothèque personnelle est vide ; les résultats en ligne n’y entrent pas automatiquement.', 'Ouvrez Ajouter des partitions et choisissez des fichiers ou un dossier dans le sélecteur Android. Plusieurs PDF, JPEG, PNG, WebP statique et un profil TIFF Group 4 noir et blanc limité sont acceptés.', 'Vérifiez la sélection. L’application conserve une copie contrôlée sans toucher à l’original externe. Vous pourrez corriger les détails incertains ensuite.'],
      pl: ['Dodaj pierwsze nuty', 'Nowa biblioteka osobista jest pusta; wyniki wyszukiwania online nie trafiają do niej automatycznie.', 'Otwórz Dodaj nuty i wybierz pliki lub folder w selektorze Androida. Możesz wybrać wiele plików PDF; obsługiwane są też JPEG, PNG, statyczny WebP i ograniczony czarno-biały TIFF Group 4.', 'Sprawdź wybór. Aplikacja zapisuje zweryfikowaną kopię bez zmiany zewnętrznego oryginału. Niepewne dane poprawisz później.'],
    },
  },
  {
    id: 'import-inbox', category: 'start', image: 'inbox.png', text: {
      ru: ['Очередь импорта и повторная попытка', 'Очередь показывает каждое задание и его итог. К ней можно вернуться после выхода с экрана импорта.', 'В библиотеке откройте меню с тремя точками → «Импорт». Посмотрите число найденных, сохранённых, пропущенных и ошибочных файлов. Нажмите «Показать файлы», чтобы увидеть отдельные позиции и те, которым нужна проверка.', 'До запуска можно снять отметку с лишнего файла; начатое задание можно приостановить или возобновить. Для исправимой ошибки используйте «Повторить», а при совпадении файла осознанно выберите существующую запись, отдельную копию или пропуск. Уже сохранённые ноты не исчезают из-за ошибки соседнего файла.'],
      en: ['Import inbox and retry', 'The inbox shows each import job and its outcome. You can return after leaving the import screen.', 'In Library open the three-dot menu → Import. Check found, saved, skipped and failed counts. Press Show files to inspect individual items and those needing review.', 'Before starting, deselect files you do not want; you can pause or resume a running job. Use Retry for a recoverable failure. For an identical file, choose the existing item, a separate copy or Skip deliberately. A failure in one file does not remove scores already saved.'],
      de: ['Importliste und erneuter Versuch', 'Die Importliste zeigt jedes Vorhaben und sein Ergebnis. Sie bleibt auch nach Verlassen der Ansicht erreichbar.', 'Öffnen Sie in der Bibliothek das Menü mit drei Punkten → Import. Prüfen Sie gefundene, gespeicherte, übersprungene und fehlerhafte Dateien. Über Dateien anzeigen sehen Sie einzelne Einträge und offene Prüfungen.', 'Vor dem Start können Sie Dateien abwählen; laufende Arbeiten lassen sich pausieren und fortsetzen. Bei behebbaren Fehlern wählen Sie Wiederholen. Bei einem Duplikat entscheiden Sie zwischen vorhandenem Eintrag, getrennter Kopie und Überspringen. Bereits gespeicherte Noten bleiben erhalten.'],
      it: ['Coda di importazione e nuovo tentativo', 'La coda mostra ogni operazione e il suo esito. Puoi tornarci dopo aver lasciato la schermata.', 'In Biblioteca apri il menu con tre punti → Importazione. Controlla i file trovati, salvati, saltati e falliti. Tocca Mostra file per vedere gli elementi e quelli da rivedere.', 'Prima di iniziare deseleziona i file superflui; puoi sospendere o riprendere un’operazione. Usa Riprova per un errore recuperabile. Per un duplicato scegli consapevolmente la voce esistente, una copia distinta o Salta. I file già salvati restano.'],
      es: ['Cola de importación y reintento', 'La cola muestra cada tarea y su resultado. Puedes volver después de salir de la pantalla.', 'En Biblioteca abre el menú de tres puntos → Importación. Revisa cuántos archivos se encontraron, guardaron, omitieron o fallaron. Pulsa Mostrar archivos para ver cada elemento y los pendientes de revisión.', 'Antes de empezar desmarca lo que no quieras; puedes pausar o reanudar una tarea. Usa Reintentar ante un fallo recuperable. Si el archivo es idéntico, elige la entrada existente, una copia aparte u Omitir. Las partituras ya guardadas permanecen.'],
      pt: ['Fila de importação e nova tentativa', 'A fila mostra cada tarefa e o seu resultado. Pode voltar depois de sair do ecrã.', 'Na Biblioteca abra o menu de três pontos → Importação. Veja quantos ficheiros foram encontrados, guardados, ignorados ou falharam. Prima Mostrar ficheiros para ver cada item e os que precisam de revisão.', 'Antes de começar desmarque ficheiros indesejados; pode pausar ou retomar a tarefa. Use Tentar novamente para uma falha recuperável. Se o ficheiro for igual, escolha o item existente, uma cópia separada ou Ignorar. As partituras já guardadas permanecem.'],
      uk: ['Черга імпорту й повторна спроба', 'Черга показує кожне завдання та його результат. До неї можна повернутися після виходу з екрана імпорту.', 'У бібліотеці відкрийте меню з трьома крапками → «Імпорт». Перегляньте кількість знайдених, збережених, пропущених і помилкових файлів. Натисніть «Показати файли», щоб побачити окремі позиції та ті, що потребують перевірки.', 'До початку зніміть позначку із зайвих файлів; завдання можна призупинити й відновити. Для виправної помилки натисніть «Повторити». Для дубліката виберіть наявний запис, окрему копію або пропуск. Уже збережені ноти залишаються.'],
      fr: ['File d’import et nouvel essai', 'La file montre chaque tâche et son résultat. Vous pouvez y revenir après avoir quitté l’écran.', 'Dans Bibliothèque, ouvrez le menu à trois points → Import. Vérifiez les nombres trouvés, enregistrés, ignorés ou en échec. Appuyez sur Afficher les fichiers pour voir chaque élément et ceux à vérifier.', 'Avant de lancer, décochez les fichiers inutiles ; vous pouvez suspendre ou reprendre la tâche. Réessayez après un échec récupérable. Pour un doublon, choisissez l’entrée existante, une copie séparée ou Ignorer. Les partitions déjà enregistrées restent présentes.'],
      pl: ['Kolejka importu i ponowienie', 'Kolejka pokazuje każde zadanie i wynik. Możesz do niej wrócić po opuszczeniu ekranu.', 'W Bibliotece otwórz menu z trzema kropkami → Import. Sprawdź liczby znalezionych, zapisanych, pominiętych i błędnych plików. Naciśnij Pokaż pliki, aby zobaczyć pozycje wymagające kontroli.', 'Przed startem odznacz niepotrzebne pliki; zadanie można wstrzymać i wznowić. Dla błędu możliwego do naprawienia użyj Ponów. Przy duplikacie wybierz istniejący wpis, osobną kopię lub Pomiń. Zapisane już nuty pozostają.'],
    },
  },
  {
    id: 'import-review', category: 'start', image: 'import.png', text: {
      ru: ['Импорт папки и проверка сведений', 'Для большой подборки удобнее выбрать папку, а затем подтвердить состав импорта.', 'После выбора папки проверьте найденные файлы и исключите лишнее. Для набора изображений выберите отдельные ноты или один документ с порядком страниц; до запуска можно повернуть и переставить страницы.', 'Следите за статусом каждого файла в импорте. Удачные позиции остаются в библиотеке, даже если другой файл не прошёл проверку; сведения о произведении и партии можно уточнить в карточке.'],
      en: ['Import a folder and review details', 'For a large set, choose a folder and check the import list before starting.', 'After selecting the folder, review the files and exclude anything unwanted. For images, choose separate scores or one ordered document; rotate and reorder pages before import.', 'Watch each file’s import status. Successful items remain in the library if another fails. You can later refine work and part details on the score card.'],
      de: ['Ordner importieren und Angaben prüfen', 'Bei vielen Dateien wählen Sie einen Ordner und prüfen die Importliste vor dem Start.', 'Prüfen Sie die gefundenen Dateien und schließen Sie Unerwünschtes aus. Bilder können einzelne Noten oder ein geordnetes Dokument bilden; Seiten lassen sich vorher drehen und sortieren.', 'Beachten Sie den Status jeder Datei. Erfolgreiche Einträge bleiben erhalten, auch wenn eine andere Datei fehlschlägt. Werk und Stimme können Sie später bearbeiten.'],
      it: ['Importare una cartella e controllare i dati', 'Per molti file scegli una cartella e controlla l’elenco prima di iniziare.', 'Escludi i file superflui. Le immagini possono diventare spartiti separati o un documento ordinato; prima dell’importazione puoi ruotare e riordinare le pagine.', 'Controlla lo stato di ogni file. Gli elementi riusciti restano in biblioteca anche se un altro fallisce. Puoi completare opera e parte in seguito.'],
      es: ['Importar una carpeta y revisar datos', 'Para muchos archivos, selecciona una carpeta y revisa la lista antes de empezar.', 'Excluye los archivos que no quieras. Las imágenes pueden formar partituras separadas o un documento ordenado; puedes girar y reordenar páginas antes de importar.', 'Comprueba el estado de cada archivo. Los elementos correctos permanecen aunque otro falle. Puedes ajustar los datos de obra y parte después.'],
      pt: ['Importar uma pasta e rever dados', 'Para muitos ficheiros, escolha uma pasta e reveja a lista antes de começar.', 'Exclua os ficheiros desnecessários. As imagens podem formar partituras separadas ou um documento ordenado; rode e reordene as páginas antes da importação.', 'Acompanhe o estado de cada ficheiro. Os itens concluídos ficam na biblioteca mesmo que outro falhe. Pode corrigir a obra e a parte depois.'],
      uk: ['Імпорт папки та перевірка даних', 'Для великої добірки виберіть папку й перевірте список до початку.', 'Вилучіть зайві файли. Зображення можна додати як окремі ноти або один документ у заданому порядку; сторінки можна повернути й переставити.', 'Стежте за станом кожного файлу. Успішні позиції залишаться, навіть якщо інший файл не пройде перевірку. Дані твору й партії можна уточнити пізніше.'],
      fr: ['Importer un dossier et vérifier les détails', 'Pour un grand ensemble, choisissez un dossier et contrôlez la liste avant de lancer l’import.', 'Écartez les fichiers inutiles. Les images peuvent devenir des partitions séparées ou un document ordonné ; tournez et réorganisez les pages avant l’import.', 'Suivez l’état de chaque fichier. Les éléments réussis restent dans la bibliothèque si un autre échoue. Vous pourrez préciser l’œuvre et la partie ensuite.'],
      pl: ['Import folderu i kontrola danych', 'Przy większym zbiorze wybierz folder i sprawdź listę przed rozpoczęciem.', 'Wyklucz zbędne pliki. Obrazy mogą stać się osobnymi nutami lub jednym dokumentem z ustaloną kolejnością; strony można wcześniej obrócić i przestawić.', 'Sprawdzaj stan każdego pliku. Udane pozycje pozostają w bibliotece, nawet gdy inny plik zawiedzie. Dane utworu i partii poprawisz później.'],
    },
  },
  {
    id: 'online-sources', category: 'start', image: 'add.png', text: {
      ru: ['Найти издание в интернете', 'Поиск в источниках отделён от локальной библиотеки и требует сети.', 'В «Добавить ноты» выберите «Найти в интернете» и явно запустите запрос. Сравните издание, право использования и региональные ограничения на странице источника.', 'Если конкретный файл разрешено скачать, сохраните проверенную копию. Иначе откройте сайт источника или сохраните ссылку: ссылка сама по себе не создаёт локальный PDF.'],
      en: ['Find an edition online', 'Source discovery is separate from your local library and needs a connection.', 'From Add scores choose Find online and explicitly run the search. Check the edition, usage rights and regional restrictions on the source page.', 'If direct download is permitted for that file, save a verified copy. Otherwise open the source site or save a reference; a reference does not create a local PDF.'],
      de: ['Eine Ausgabe online finden', 'Die Quellensuche ist von der lokalen Bibliothek getrennt und benötigt Internet.', 'Wählen Sie unter Noten hinzufügen „Online suchen“ und starten Sie die Suche ausdrücklich. Prüfen Sie Ausgabe, Nutzungsrechte und regionale Grenzen an der Quelle.', 'Ist der direkte Download erlaubt, speichern Sie eine geprüfte Kopie. Sonst öffnen Sie die Quellseite oder speichern einen Verweis; ein Verweis ist kein lokales PDF.'],
      it: ['Trovare un’edizione online', 'La ricerca nelle fonti è separata dalla biblioteca locale e richiede internet.', 'Da Aggiungi spartiti scegli Cerca online e avvia la ricerca. Controlla edizione, diritti d’uso e limiti regionali sulla pagina della fonte.', 'Se il download diretto è consentito, salva una copia verificata. Altrimenti apri la fonte o conserva un collegamento; il collegamento non crea un PDF locale.'],
      es: ['Encontrar una edición en línea', 'La búsqueda en fuentes está separada de la biblioteca local y necesita conexión.', 'Desde Añadir partituras elige Buscar en línea e inicia la búsqueda. Comprueba edición, derechos y límites regionales en la fuente.', 'Si se permite descargar ese archivo, guarda una copia verificada. Si no, abre la fuente o guarda el enlace; el enlace no crea un PDF local.'],
      pt: ['Encontrar uma edição online', 'A pesquisa de fontes é separada da biblioteca local e precisa de ligação.', 'Em Adicionar partituras escolha Pesquisar online e inicie a pesquisa. Confirme a edição, direitos de uso e limites regionais na fonte.', 'Se a transferência direta for permitida, guarde uma cópia verificada. Caso contrário, abra a fonte ou guarde a ligação; uma ligação não cria um PDF local.'],
      uk: ['Знайти видання в інтернеті', 'Пошук у джерелах відокремлений від локальної бібліотеки й потребує мережі.', 'У «Додати ноти» виберіть пошук в інтернеті та явно запустіть запит. На сторінці джерела перевірте видання, права й регіональні обмеження.', 'Якщо файл дозволено завантажити напряму, збережіть перевірену копію. Інакше відкрийте джерело або збережіть посилання; посилання не створює локальний PDF.'],
      fr: ['Trouver une édition en ligne', 'La recherche dans les sources est distincte de la bibliothèque locale et nécessite internet.', 'Depuis Ajouter des partitions, choisissez la recherche en ligne et lancez-la explicitement. Vérifiez l’édition, les droits et les restrictions régionales à la source.', 'Si le téléchargement direct est autorisé, enregistrez une copie vérifiée. Sinon, ouvrez la source ou gardez un lien ; un lien ne crée pas de PDF local.'],
      pl: ['Znajdź wydanie online', 'Wyszukiwanie źródeł jest oddzielone od biblioteki i wymaga internetu.', 'W Dodaj nuty wybierz wyszukiwanie online i uruchom je świadomie. Sprawdź wydanie, prawa i ograniczenia regionalne na stronie źródła.', 'Jeśli pobranie jest dozwolone, zapisz zweryfikowaną kopię. W przeciwnym razie otwórz źródło lub zachowaj odnośnik; odnośnik nie tworzy lokalnego PDF.'],
    },
  },
  {
    id: 'find-in-library', category: 'library', image: 'search.png', text: {
      ru: ['Найти ноты в библиотеке', 'Локальный поиск работает без интернета и не отправляет введённое внешним источникам.', 'Введите название, композитора, номер опуса, имя файла, партию, тег или коллекцию. Можно использовать кириллицу, латиницу и привычное написание имени.', 'Уточните список фильтрами «Избранное», «Недавние», «Доступно офлайн», «Недоступно» и сортировкой. Поиск не распознаёт нотный текст внутри скана.'],
      en: ['Find scores in your library', 'Library search works offline and does not send what you type to online sources.', 'Enter a title, composer, opus number, filename, part, tag or collection. Cyrillic, Latin spellings and common name variants are supported.', 'Narrow the list with Favorites, Recent, Available offline, Missing and sorting. Search does not recognise notation inside a scan.'],
      de: ['Noten in der Bibliothek finden', 'Die Bibliothekssuche funktioniert offline und sendet Eingaben nicht an Online-Quellen.', 'Suchen Sie nach Titel, Komponist, Opuszahl, Dateiname, Stimme, Tag oder Sammlung. Kyrillische und lateinische Schreibweisen werden berücksichtigt.', 'Grenzen Sie die Liste mit Favoriten, Zuletzt, Offline verfügbar, Fehlend und Sortierung ein. Notenschrift in Scans wird nicht erkannt.'],
      it: ['Trovare spartiti in biblioteca', 'La ricerca nella biblioteca funziona offline e non invia le parole alle fonti online.', 'Cerca titolo, compositore, numero d’opera, file, parte, tag o raccolta. Sono considerate grafie cirilliche e latine.', 'Restringi con Preferiti, Recenti, Disponibili offline, Mancanti e ordinamento. La ricerca non riconosce la notazione in una scansione.'],
      es: ['Buscar partituras en la biblioteca', 'La búsqueda local funciona sin conexión y no envía el texto a fuentes externas.', 'Busca título, compositor, opus, nombre de archivo, parte, etiqueta o colección. Se admiten grafías cirílicas y latinas.', 'Filtra por Favoritos, Recientes, Disponibles sin conexión o Faltantes y ordena la lista. No se reconoce la notación dentro de un escaneo.'],
      pt: ['Encontrar partituras na biblioteca', 'A pesquisa local funciona offline e não envia o texto a fontes externas.', 'Pesquise título, compositor, opus, nome do ficheiro, parte, etiqueta ou coleção. São consideradas grafias cirílicas e latinas.', 'Use Favoritos, Recentes, Disponível offline, Em falta e ordenação. A pesquisa não reconhece notação dentro de digitalizações.'],
      uk: ['Знайти ноти в бібліотеці', 'Локальний пошук працює без інтернету й не надсилає введений текст зовнішнім джерелам.', 'Шукайте за назвою, композитором, опусом, назвою файлу, партією, тегом або колекцією. Підтримуються кирилиця й латиниця.', 'Звужуйте список фільтрами «Обране», «Нещодавні», «Офлайн», «Недоступні» й сортуванням. Нотний текст у скані не розпізнається.'],
      fr: ['Retrouver une partition', 'La recherche dans la bibliothèque fonctionne hors connexion sans transmettre votre saisie aux sources.', 'Saisissez titre, compositeur, opus, nom du fichier, partie, étiquette ou collection. Les graphies cyrilliques et latines sont prises en compte.', 'Affinez avec Favoris, Récents, Disponibles hors ligne, Manquants et le tri. Les notes imprimées dans un scan ne sont pas reconnues.'],
      pl: ['Znajdź nuty w bibliotece', 'Wyszukiwanie lokalne działa bez internetu i nie wysyła wpisanego tekstu do źródeł.', 'Wpisz tytuł, kompozytora, opus, nazwę pliku, partię, tag lub kolekcję. Uwzględniane są zapisy cyrylicą i alfabetem łacińskim.', 'Zawęź listę filtrami Ulubione, Ostatnie, Offline, Brakujące i sortowaniem. Nuty na skanie nie są rozpoznawane.'],
    },
  },
  {
    id: 'score-details', category: 'library', image: 'review.png', text: {
      ru: ['Исправить сведения и обложку', 'Название, композитор, партия и личные пометки помогают находить нужное издание.', 'Откройте меню карточки нот и перейдите к сведениям. Исправьте поля, добавьте теги или отметьте избранное; после сохранения они участвуют в локальном поиске.', 'Для своей карточки можно выбрать или сбросить обложку, кадрировать и повернуть изображение. Внешний оригинал нот от этого не изменится.'],
      en: ['Edit details and cover', 'Title, composer, part and personal notes help you find the right edition.', 'Open the score card menu and choose its information. Correct fields, add tags or mark a favorite; saved details join local search.', 'Choose, crop, rotate or reset a personal cover. This does not alter the external score original.'],
      de: ['Angaben und Cover bearbeiten', 'Titel, Komponist, Stimme und persönliche Notizen helfen beim Auffinden einer Ausgabe.', 'Öffnen Sie das Menü der Notenkarte und die Informationen. Korrigieren Sie Felder, vergeben Sie Tags oder markieren Sie Favoriten; gespeicherte Angaben werden lokal gesucht.', 'Ein eigenes Cover können Sie wählen, zuschneiden, drehen oder zurücksetzen. Das externe Notenoriginal bleibt unverändert.'],
      it: ['Modificare dati e copertina', 'Titolo, compositore, parte e note personali aiutano a trovare l’edizione giusta.', 'Apri il menu della scheda e le informazioni. Correggi i campi, aggiungi tag o preferiti; i dati salvati entrano nella ricerca locale.', 'Puoi scegliere, ritagliare, ruotare o ripristinare una copertina personale. L’originale esterno non cambia.'],
      es: ['Editar datos y portada', 'Título, compositor, parte y notas personales ayudan a encontrar la edición adecuada.', 'Abre el menú de la tarjeta y sus datos. Corrige campos, añade etiquetas o márcala como favorita; los datos guardados entran en la búsqueda local.', 'Elige, recorta, gira o restablece una portada personal. El original externo no cambia.'],
      pt: ['Editar dados e capa', 'Título, compositor, parte e notas pessoais ajudam a encontrar a edição certa.', 'Abra o menu da partitura e as informações. Corrija campos, adicione etiquetas ou favoritos; os dados guardados entram na pesquisa local.', 'Escolha, recorte, rode ou reponha uma capa pessoal. O original externo não é alterado.'],
      uk: ['Виправити дані й обкладинку', 'Назва, композитор, партія та особисті нотатки допомагають знайти видання.', 'Відкрийте меню картки та відомості. Виправте поля, додайте теги або позначте обране; збережені дані потраплять до локального пошуку.', 'Власну обкладинку можна вибрати, обрізати, повернути чи скинути. Зовнішній оригінал не змінюється.'],
      fr: ['Modifier les détails et la couverture', 'Titre, compositeur, partie et notes personnelles aident à retrouver une édition.', 'Ouvrez le menu de la fiche puis ses informations. Corrigez les champs, ajoutez des étiquettes ou un favori ; ils deviennent cherchables localement.', 'Choisissez, recadrez, tournez ou réinitialisez une couverture personnelle. L’original externe reste intact.'],
      pl: ['Popraw dane i okładkę', 'Tytuł, kompozytor, partia i własne notatki pomagają znaleźć wydanie.', 'Otwórz menu karty nut i informacje. Popraw pola, dodaj tagi lub oznacz ulubione; zapisane dane są objęte wyszukiwaniem lokalnym.', 'Możesz wybrać, przyciąć, obrócić lub zresetować własną okładkę. Zewnętrzny oryginał pozostaje bez zmian.'],
    },
  },
  {
    id: 'collections-and-batch', category: 'library', image: 'collections.png', text: {
      ru: ['Коллекции и действия с несколькими нотами', 'Коллекция собирает ссылки на ноты из библиотеки; добавление в неё не копирует документ.', 'Откройте «Коллекции», создайте коллекцию и выберите из своей библиотеки нужные позиции. Можно также начать импорт прямо из коллекции. Удаление коллекции сохраняет её ноты в библиотеке.', 'На главном экране переключайте плитки и список. Для массовых действий включите выбор карточек, проверьте отмеченные позиции и затем примените команду из меню выбора.'],
      en: ['Collections and batch actions', 'A collection refers to scores already in your library; it does not copy their documents.', 'Open Collections, create one, and choose library items. You can also start an import from inside a collection. Deleting a collection leaves its scores in the library.', 'Switch between tiles and list view. For batch work, start card selection, review the selected scores, then choose a command from the selection menu.'],
      de: ['Sammlungen und Mehrfachaktionen', 'Eine Sammlung verweist auf Noten Ihrer Bibliothek und kopiert deren Dokumente nicht.', 'Öffnen Sie Sammlungen, legen Sie eine an und wählen Sie vorhandene Noten. Auch ein Import aus der Sammlung ist möglich. Beim Löschen bleiben die Noten in der Bibliothek.', 'Wechseln Sie zwischen Kacheln und Liste. Für mehrere Noten starten Sie die Auswahl, prüfen die Markierungen und wählen eine Aktion im Auswahlmenü.'],
      it: ['Raccolte e azioni multiple', 'Una raccolta fa riferimento agli spartiti già in biblioteca; non duplica i documenti.', 'Apri Raccolte, creane una e scegli gli elementi. Puoi anche avviare un’importazione dalla raccolta. Eliminare la raccolta lascia gli spartiti in biblioteca.', 'Alterna griglia ed elenco. Per azioni multiple avvia la selezione, controlla gli elementi e scegli il comando nel menu.'],
      es: ['Colecciones y acciones en lote', 'Una colección enlaza partituras de tu biblioteca; no duplica los documentos.', 'Abre Colecciones, crea una y elige elementos existentes. También puedes importar desde ella. Al borrar una colección, las partituras siguen en la biblioteca.', 'Alterna mosaico y lista. Para actuar sobre varias partituras, inicia la selección, revísala y usa el menú de selección.'],
      pt: ['Coleções e ações em lote', 'Uma coleção referencia partituras da biblioteca; não duplica documentos.', 'Abra Coleções, crie uma e escolha os itens. Também pode importar a partir dela. Apagar a coleção mantém as partituras na biblioteca.', 'Alterne mosaicos e lista. Para agir sobre vários itens, inicie a seleção, confirme os marcados e use o menu de seleção.'],
      uk: ['Колекції та масові дії', 'Колекція посилається на ноти бібліотеки й не копіює документи.', 'Відкрийте «Колекції», створіть колекцію та виберіть записи. Імпорт можна почати й із колекції. Її видалення не прибирає ноти з бібліотеки.', 'Перемикайте плитки й список. Для масових дій увімкніть вибір, перевірте позначені ноти та застосуйте команду з меню.'],
      fr: ['Collections et actions groupées', 'Une collection renvoie aux partitions de la bibliothèque sans copier leurs documents.', 'Ouvrez Collections, créez-en une et choisissez les éléments existants. Vous pouvez aussi importer depuis la collection. Sa suppression laisse les partitions dans la bibliothèque.', 'Passez des vignettes à la liste. Pour agir sur plusieurs partitions, lancez la sélection, vérifiez-la puis utilisez son menu.'],
      pl: ['Kolekcje i działania zbiorcze', 'Kolekcja odsyła do nut w bibliotece, nie kopiuje dokumentów.', 'Otwórz Kolekcje, utwórz kolekcję i wybierz pozycje. Możesz też rozpocząć import w kolekcji. Usunięcie kolekcji pozostawia nuty w bibliotece.', 'Przełączaj kafelki i listę. Do działań zbiorczych włącz wybór, sprawdź zaznaczone nuty i wybierz polecenie z menu.'],
    },
  },
  {
    id: 'smart-collections', category: 'library', access: 'pro', text: {
      ru: ['Умные коллекции и проверяемые действия', 'Умная коллекция показывает подходящие ноты по локальным условиям, не создавая копий файлов.', 'Задайте понятные условия: избранное, доступность, инструмент, тег, коллекция или сохранённый поиск. Перед повторяемым массовым действием просмотрите точный список затрагиваемых нот и подтвердите его.', 'История позволяет отменить завершённое действие в предусмотренных случаях. Обычные теги, коллекции и выбор нескольких карточек остаются бесплатными; создание автоматизации требует Pro.'],
      en: ['Smart collections and reviewed actions', 'A smart collection shows matching local scores without making file copies.', 'Set visible conditions such as favorites, availability, instrument, tag, collection or saved search. Before a repeatable batch action, inspect the exact affected list and confirm it.', 'Action history supports undo where available. Ordinary tags, collections and multi-selection remain Free; creating automation needs Pro.'],
      de: ['Intelligente Sammlungen und geprüfte Aktionen', 'Eine intelligente Sammlung zeigt passende lokale Noten, ohne Dateien zu kopieren.', 'Legen Sie sichtbare Bedingungen wie Favoriten, Verfügbarkeit, Instrument, Tag, Sammlung oder Suche fest. Prüfen Sie vor wiederholbaren Mehrfachaktionen die betroffene Liste und bestätigen Sie sie.', 'Die Historie ermöglicht gegebenenfalls Rücknahme. Normale Tags, Sammlungen und Mehrfachauswahl bleiben kostenlos; neue Automatisierung benötigt Pro.'],
      it: ['Raccolte intelligenti e azioni controllate', 'Una raccolta intelligente mostra spartiti locali corrispondenti senza duplicare file.', 'Imposta condizioni visibili: preferiti, disponibilità, strumento, tag, raccolta o ricerca. Prima di un’azione multipla ripetibile controlla l’elenco esatto e conferma.', 'La cronologia consente l’annullamento quando previsto. Tag, raccolte e selezione multipla ordinari restano gratuiti; creare automazioni richiede Pro.'],
      es: ['Colecciones inteligentes y acciones revisadas', 'Una colección inteligente muestra partituras locales coincidentes sin copiar archivos.', 'Define condiciones visibles: favoritos, disponibilidad, instrumento, etiqueta, colección o búsqueda. Antes de una acción en lote repetible revisa la lista exacta y confirma.', 'El historial permite deshacer cuando corresponde. Etiquetas, colecciones y selección múltiple normales siguen siendo gratis; crear automatizaciones requiere Pro.'],
      pt: ['Coleções inteligentes e ações revistas', 'Uma coleção inteligente mostra partituras locais que correspondem às condições sem copiar ficheiros.', 'Defina condições visíveis: favoritos, disponibilidade, instrumento, etiqueta, coleção ou pesquisa. Antes de uma ação em lote repetível reveja a lista exata e confirme.', 'O histórico permite desfazer quando disponível. Etiquetas, coleções e seleção múltipla comuns continuam gratuitas; criar automatizações exige Pro.'],
      uk: ['Розумні колекції та перевірені дії', 'Розумна колекція показує відповідні локальні ноти, не копіюючи файлів.', 'Задайте видимі умови: обране, доступність, інструмент, тег, колекцію чи пошук. Перед повторюваною масовою дією перегляньте точний список і підтвердьте.', 'Історія дає змогу скасувати дію, де це підтримується. Звичайні теги, колекції й груповий вибір безкоштовні; нова автоматизація потребує Pro.'],
      fr: ['Collections intelligentes et actions contrôlées', 'Une collection intelligente montre les partitions locales correspondantes sans copier les fichiers.', 'Définissez des critères visibles : favoris, disponibilité, instrument, étiquette, collection ou recherche. Avant une action groupée répétable, vérifiez la liste exacte et confirmez.', 'L’historique permet l’annulation quand elle existe. Étiquettes, collections et sélection multiple ordinaires restent gratuites ; créer une automatisation demande Pro.'],
      pl: ['Inteligentne kolekcje i sprawdzane działania', 'Inteligentna kolekcja pokazuje pasujące lokalne nuty bez kopiowania plików.', 'Ustaw widoczne warunki: ulubione, dostępność, instrument, tag, kolekcję lub wyszukiwanie. Przed powtarzalnym działaniem zbiorczym sprawdź dokładną listę i potwierdź.', 'Historia umożliwia cofnięcie tam, gdzie jest dostępne. Zwykłe tagi, kolekcje i wielokrotny wybór są bezpłatne; tworzenie automatyzacji wymaga Pro.'],
    },
  },
  {
    id: 'reader', category: 'reading', image: 'viewer.png', text: {
      ru: ['Открыть и читать ноты', 'Просмотр сохраняет место чтения и оставляет нотную страницу главным элементом экрана.', 'Откройте ноты из библиотеки или блока продолжения. Перелистывайте страницы касанием или доступными временными элементами управления. Вызовите инструменты, когда нужно перейти к странице или выйти.', 'Масштаб и кадрирование настраиваются в просмотре. Если приложение сообщает, что место чтения не сохранилось, можно продолжать, но проверьте свободное место устройства.'],
      en: ['Open and read a score', 'The reader keeps your place and gives the score page the screen.', 'Open a score from the library or Continue. Turn pages with touch or the temporary controls; reveal tools when you need a page jump or exit.', 'Adjust zoom and crop in the reader. If saving your place fails, you may keep reading, but check free device storage.'],
      de: ['Noten öffnen und lesen', 'Der Betrachter merkt sich die Stelle und gibt der Notenseite den Raum.', 'Öffnen Sie Noten aus der Bibliothek oder über Fortsetzen. Blättern Sie per Berührung oder mit den zeitweise eingeblendeten Steuerelementen; rufen Sie Werkzeuge bei Bedarf auf.', 'Zoom und Beschnitt lassen sich anpassen. Kann die Stelle nicht gespeichert werden, können Sie weiterlesen; prüfen Sie dann den freien Speicher.'],
      it: ['Aprire e leggere uno spartito', 'Il lettore ricorda la posizione e lascia spazio alla pagina musicale.', 'Apri uno spartito dalla biblioteca o da Continua. Gira pagina con il tocco o i controlli temporanei; mostra gli strumenti per saltare a una pagina o uscire.', 'Regola ingrandimento e ritaglio. Se la posizione non viene salvata puoi continuare a leggere, ma verifica lo spazio libero.'],
      es: ['Abrir y leer una partitura', 'El lector recuerda la posición y da prioridad a la página musical.', 'Abre la partitura desde la biblioteca o Continuar. Pasa páginas tocando o con los controles temporales; muestra las herramientas para ir a una página o salir.', 'Ajusta zoom y recorte. Si no se guarda la posición, puedes seguir leyendo, pero comprueba el espacio libre.'],
      pt: ['Abrir e ler uma partitura', 'O leitor guarda a posição e dá prioridade à página musical.', 'Abra uma partitura na biblioteca ou em Continuar. Vire páginas pelo toque ou com controlos temporários; mostre as ferramentas para saltar de página ou sair.', 'Ajuste zoom e recorte. Se a posição não for guardada, pode continuar a ler, mas verifique o espaço livre.'],
      uk: ['Відкрити й читати ноти', 'Переглядач зберігає місце читання й віддає екран нотній сторінці.', 'Відкрийте ноти з бібліотеки або «Продовжити». Гортайте дотиком чи тимчасовими елементами; викликайте інструменти для переходу до сторінки або виходу.', 'Налаштовуйте масштаб і обрізання. Якщо місце не вдалося зберегти, можна читати далі, але перевірте вільну пам’ять.'],
      fr: ['Ouvrir et lire une partition', 'Le lecteur garde votre place et privilégie la page musicale.', 'Ouvrez une partition depuis la bibliothèque ou Reprendre. Tournez les pages au toucher ou avec les commandes temporaires ; affichez les outils pour changer de page ou quitter.', 'Réglez le zoom et le recadrage. Si la position ne s’enregistre pas, vous pouvez continuer à lire, mais vérifiez l’espace libre.'],
      pl: ['Otwórz i czytaj nuty', 'Czytnik zapamiętuje miejsce i oddaje ekran stronie z nutami.', 'Otwórz nuty z biblioteki lub Kontynuuj. Zmieniaj strony dotykiem albo tymczasowymi przyciskami; pokaż narzędzia, gdy chcesz przejść do strony lub wyjść.', 'Ustaw powiększenie i kadrowanie. Jeśli zapis miejsca się nie uda, możesz czytać dalej, ale sprawdź wolną pamięć.'],
    },
  },
  {
    id: 'reading-profiles', category: 'reading', access: 'pro', text: {
      ru: ['Настроить показ страниц', 'Профили чтения сохраняют вид конкретной редакции: кадрирование, половины страницы, развороты и порядок.', 'Откройте инструменты просмотра и настройте профиль. Используйте закладки и заметки для точных мест; повторные переходы задавайте явно, чтобы во время исполнения не менять порядок случайно.', 'Сохранённый профиль остаётся доступен для чтения, применения, экспорта и восстановления после окончания Pro. Новое редактирование профилей требует подтверждённого права.'],
      en: ['Set up page display', 'Reading profiles keep an exact edition’s crop, half pages, spreads and page order.', 'Open reader tools and set a profile. Use bookmarks and notes for exact places; add repeat links deliberately so performance order is predictable.', 'Saved profiles stay readable, applicable, exportable and recoverable after Pro ends. New profile editing needs verified access.'],
      de: ['Seitenanzeige einrichten', 'Leseprofile speichern Beschnitt, Halbseiten, Doppelseiten und Reihenfolge einer bestimmten Ausgabe.', 'Öffnen Sie die Leserwerkzeuge und richten Sie ein Profil ein. Setzen Sie Lesezeichen und Notizen; Wiederholungen legen Sie bewusst fest.', 'Gespeicherte Profile bleiben auch nach Pro lesbar, anwendbar, exportierbar und wiederherstellbar. Neue Bearbeitung braucht bestätigten Zugang.'],
      it: ['Impostare la visualizzazione', 'I profili conservano ritaglio, mezze pagine, doppie pagine e ordine di una precisa edizione.', 'Apri gli strumenti di lettura e imposta un profilo. Usa segnalibri e note per i punti esatti; definisci i salti di ripetizione esplicitamente.', 'I profili salvati restano leggibili, applicabili, esportabili e recuperabili dopo Pro. Nuove modifiche richiedono accesso verificato.'],
      es: ['Configurar las páginas', 'Los perfiles guardan recorte, medias páginas, páginas enfrentadas y orden de una edición exacta.', 'Abre las herramientas del lector y configura un perfil. Usa marcadores y notas; define los saltos de repetición expresamente.', 'Los perfiles guardados siguen disponibles para leer, aplicar, exportar y recuperar tras Pro. Editar uno nuevo requiere acceso verificado.'],
      pt: ['Configurar as páginas', 'Os perfis guardam recorte, meias páginas, páginas duplas e ordem de uma edição exata.', 'Abra as ferramentas do leitor e configure um perfil. Use marcadores e notas; defina saltos de repetição de forma explícita.', 'Perfis guardados continuam legíveis, aplicáveis, exportáveis e recuperáveis após Pro. Nova edição exige acesso confirmado.'],
      uk: ['Налаштувати показ сторінок', 'Профілі зберігають обрізання, половини, розвороти й порядок сторінок певного видання.', 'Відкрийте інструменти переглядача й налаштуйте профіль. Використовуйте закладки та нотатки; повторні переходи задавайте явно.', 'Збережені профілі можна читати, застосовувати, експортувати й відновлювати після завершення Pro. Нове редагування потребує підтвердженого доступу.'],
      fr: ['Régler l’affichage', 'Les profils conservent recadrage, demi-pages, doubles pages et ordre d’une édition précise.', 'Ouvrez les outils du lecteur et configurez un profil. Utilisez signets et notes ; définissez les retours de répétition volontairement.', 'Les profils enregistrés restent lisibles, applicables, exportables et récupérables après Pro. Les nouvelles modifications demandent un accès vérifié.'],
      pl: ['Ustaw wyświetlanie stron', 'Profile zapisują kadrowanie, półstrony, rozkładówki i kolejność konkretnego wydania.', 'Otwórz narzędzia czytnika i ustaw profil. Korzystaj z zakładek i notatek; skoki powtórzeń określ świadomie.', 'Zapisane profile można czytać, stosować, eksportować i odzyskać po Pro. Nowa edycja wymaga potwierdzonego dostępu.'],
    },
  },
  {
    id: 'annotations', category: 'reading', access: 'pro', text: {
      ru: ['Пометки и слои', 'В просмотре есть рукописные, текстовые и музыкальные пометки, организованные по слоям.', 'Откройте рабочую область пометок на нужной странице. Выберите инструмент, проверьте видимость слоя и внесите изменение. Можно сохранить именованную версию или вернуться к предыдущей.', 'Существующие пометки можно читать, проверять, экспортировать и восстанавливать без нового Pro-доступа. Для новых правок нужен подтверждённый доступ; PDF-экспорт с пометками явно выбирает страницу.'],
      en: ['Marks and layers', 'The reader supports ink, text and musical stamps organised in layers.', 'Open the marking workspace on the right page. Choose a tool, check layer visibility and make the mark. You can save a named version or inspect an earlier one.', 'Existing marks can be read, reviewed, exported and recovered without new Pro access. New edits need verified access; annotated PDF export explicitly selects a page.'],
      de: ['Markierungen und Ebenen', 'Der Leser unterstützt Freihandstriche, Text und musikalische Stempel auf Ebenen.', 'Öffnen Sie den Markierungsbereich auf der Seite. Wählen Sie ein Werkzeug, prüfen Sie die Ebenensichtbarkeit und markieren Sie. Benannte Versionen können gespeichert und frühere geprüft werden.', 'Vorhandene Markierungen bleiben ohne neues Pro lesbar, prüfbar, exportierbar und wiederherstellbar. Neue Änderungen brauchen bestätigten Zugang; PDF-Export wählt eine Seite.'],
      it: ['Annotazioni e livelli', 'Il lettore supporta inchiostro, testo e timbri musicali organizzati in livelli.', 'Apri l’area annotazioni sulla pagina giusta. Scegli lo strumento, controlla il livello e inserisci il segno. Puoi salvare una versione nominata o rivederne una precedente.', 'I segni esistenti restano leggibili, esportabili e recuperabili senza nuovo Pro. Per nuove modifiche serve accesso verificato; l’export PDF annotato sceglie una pagina.'],
      es: ['Anotaciones y capas', 'El lector admite tinta, texto y sellos musicales organizados por capas.', 'Abre el área de anotación en la página adecuada. Elige herramienta, comprueba la capa y marca. Puedes guardar una versión con nombre o revisar otra anterior.', 'Las marcas existentes siguen disponibles para leer, exportar y recuperar sin nuevo Pro. Crear o editar exige acceso verificado; el PDF anotado se exporta por página.'],
      pt: ['Anotações e camadas', 'O leitor suporta tinta, texto e carimbos musicais em camadas.', 'Abra a área de anotações na página certa. Escolha a ferramenta, confira a camada e marque. Pode guardar uma versão com nome ou rever outra anterior.', 'Marcas existentes continuam legíveis, exportáveis e recuperáveis sem novo Pro. Criar ou editar exige acesso confirmado; o PDF anotado é exportado por página.'],
      uk: ['Помітки та шари', 'Переглядач підтримує рукописні, текстові й музичні помітки, розкладені за шарами.', 'Відкрийте область поміток на потрібній сторінці. Виберіть інструмент, перевірте видимість шару й внесіть зміну. Можна зберегти іменовану версію або переглянути стару.', 'Наявні помітки можна читати, експортувати й відновлювати без нового Pro. Нові правки потребують доступу; PDF із помітками експортується для вибраної сторінки.'],
      fr: ['Annotations et calques', 'Le lecteur accepte traits, texte et symboles musicaux répartis en calques.', 'Ouvrez l’espace d’annotation sur la bonne page. Choisissez l’outil, vérifiez la visibilité du calque et marquez. Une version nommée peut être enregistrée ou comparée.', 'Les marques existantes restent lisibles, exportables et récupérables sans nouveau Pro. Les nouvelles modifications demandent un accès vérifié ; le PDF annoté concerne une page choisie.'],
      pl: ['Adnotacje i warstwy', 'Czytnik obsługuje rysunek, tekst i symbole muzyczne na warstwach.', 'Otwórz obszar adnotacji na właściwej stronie. Wybierz narzędzie, sprawdź widoczność warstwy i dodaj znak. Możesz zapisać nazwaną wersję lub obejrzeć wcześniejszą.', 'Istniejące znaki pozostają czytelne, eksportowalne i możliwe do odzyskania bez nowego Pro. Nowa edycja wymaga dostępu; PDF z adnotacjami dotyczy wybranej strony.'],
    },
  },
  {
    id: 'programmes', category: 'rehearsal', access: 'pro', text: {
      ru: ['Программа выступления', 'Программа хранит порядок произведений, повторы, заметки и паузы с точными версиями документов.', 'Создайте программу из библиотеки, расставьте позиции и проверьте, какая редакция и профиль чтения закреплены за каждой. Перед исполнением запустите офлайн-проверку: она покажет недоступные или изменившиеся ссылки.', 'Во время исполнения можно заблокировать лишние действия, листать ноты и явно приостановить выступление. Сохранённую программу можно читать, экспортировать и восстанавливать без нового Pro.'],
      en: ['Performance programmes', 'A programme keeps the order, repeats, notes and breaks with exact document versions.', 'Build it from your library, order the entries and check each pinned edition and reading profile. Run the offline preflight before playing; it reports missing or changed references.', 'During a run, lock incidental actions, turn pages and pause explicitly. Saved programmes remain readable, exportable and recoverable without new Pro access.'],
      de: ['Konzertprogramme', 'Ein Programm speichert Reihenfolge, Wiederholungen, Notizen und Pausen mit genauen Dokumentversionen.', 'Stellen Sie es aus der Bibliothek zusammen und prüfen Sie Ausgabe und Leseprofil jeder Position. Die Offline-Prüfung meldet fehlende oder geänderte Verweise.', 'Im Durchlauf können Sie Aktionen sperren, blättern und bewusst pausieren. Gespeicherte Programme bleiben ohne neues Pro lesbar, exportierbar und wiederherstellbar.'],
      it: ['Programmi di esecuzione', 'Un programma conserva ordine, ripetizioni, note e pause con versioni precise dei documenti.', 'Componilo dalla biblioteca e controlla edizione e profilo di ogni voce. La verifica offline segnala riferimenti mancanti o cambiati.', 'Durante l’esecuzione blocca azioni accidentali, gira pagina e metti in pausa esplicitamente. I programmi salvati restano leggibili, esportabili e recuperabili senza nuovo Pro.'],
      es: ['Programas de actuación', 'Un programa guarda orden, repeticiones, notas y pausas con versiones exactas de los documentos.', 'Constrúyelo desde la biblioteca y revisa la edición y el perfil de cada entrada. La comprobación sin conexión avisa de referencias faltantes o cambiadas.', 'Durante la actuación bloquea acciones accidentales, pasa páginas y pausa expresamente. Los programas guardados siguen disponibles para leer, exportar y recuperar sin nuevo Pro.'],
      pt: ['Programas de atuação', 'Um programa guarda ordem, repetições, notas e pausas com versões exatas dos documentos.', 'Monte-o a partir da biblioteca e confirme edição e perfil de cada entrada. A verificação offline mostra referências em falta ou alteradas.', 'Na atuação bloqueie ações acidentais, vire páginas e pause explicitamente. Programas guardados continuam legíveis, exportáveis e recuperáveis sem novo Pro.'],
      uk: ['Програма виступу', 'Програма зберігає порядок, повтори, нотатки й паузи з точними версіями документів.', 'Складіть її з бібліотеки, перевірте видання та профіль кожної позиції. Офлайн-перевірка повідомить про відсутні чи змінені посилання.', 'Під час виступу заблокуйте випадкові дії, гортайте й явно ставте на паузу. Збережені програми можна читати, експортувати та відновлювати без нового Pro.'],
      fr: ['Programmes de concert', 'Un programme garde l’ordre, les reprises, les notes et les pauses avec les versions exactes des documents.', 'Composez-le depuis la bibliothèque et vérifiez édition et profil de chaque entrée. Le contrôle hors ligne signale les références absentes ou modifiées.', 'Pendant le concert, verrouillez les actions accidentelles, tournez les pages et mettez en pause volontairement. Les programmes enregistrés restent lisibles, exportables et récupérables sans nouveau Pro.'],
      pl: ['Programy występu', 'Program zapisuje kolejność, powtórzenia, notatki i przerwy z dokładnymi wersjami dokumentów.', 'Zbuduj go z biblioteki i sprawdź wydanie oraz profil każdej pozycji. Kontrola offline zgłasza brakujące lub zmienione odniesienia.', 'Podczas występu zablokuj przypadkowe działania, zmieniaj strony i świadomie wstrzymuj. Zapisane programy można czytać, eksportować i odzyskać bez nowego Pro.'],
    },
  },
  {
    id: 'practice-tools', category: 'rehearsal', access: 'pro', text: {
      ru: ['Трудные места и план занятия', 'Рабочая область музыканта связывает задачу с конкретной страницей, областью и редакцией.', 'В открытых нотах сохраните фрагмент, укажите такт или репетиционную букву, партию и цель. Добавьте начальный и целевой темп, затем включите задачу в упорядоченный план занятия.', 'Статус меняет сам музыкант: приложение не оценивает исполнение автоматически. Если точный оригинал недоступен, ссылка не подменяется похожими нотами.'],
      en: ['Difficult passages and practice plan', 'The musician workspace ties a task to an exact page, region and edition.', 'From an open score save a passage; add a measure or rehearsal label, part and goal. Set starting and target tempo, then place the task in an ordered practice queue.', 'You set the task status yourself; the app does not assess playing automatically. A missing exact original is not replaced by a similar score.'],
      de: ['Schwierige Stellen und Übeplan', 'Der Musikerbereich bindet eine Aufgabe an genaue Seite, Bereich und Ausgabe.', 'Speichern Sie aus geöffneten Noten eine Stelle und ergänzen Sie Takt/Probezeichen, Stimme und Ziel. Tragen Sie Start- und Zieltempo ein und ordnen Sie die Aufgabe im Übeplan.', 'Den Status setzen Sie selbst; die App bewertet das Spiel nicht automatisch. Ein fehlendes Original wird nicht durch ähnliche Noten ersetzt.'],
      it: ['Passaggi difficili e piano di studio', 'L’area musicista lega un compito a pagina, zona ed edizione esatte.', 'Da uno spartito aperto salva un passaggio, indica battuta o lettera di prova, parte e obiettivo. Imposta tempo iniziale e finale e mettilo nel piano ordinato.', 'Decidi tu lo stato: l’app non valuta automaticamente l’esecuzione. Un originale mancante non viene sostituito da spartiti simili.'],
      es: ['Pasajes difíciles y plan de estudio', 'El espacio del músico vincula una tarea con página, región y edición exactas.', 'Desde una partitura abierta guarda un pasaje, añade compás o letra de ensayo, parte y objetivo. Define tempo inicial y final y ordénalo en el plan.', 'Tú cambias el estado; la app no evalúa la interpretación automáticamente. Un original faltante no se sustituye por otro parecido.'],
      pt: ['Passagens difíceis e plano de estudo', 'A área do músico liga uma tarefa a página, região e edição exatas.', 'Com a partitura aberta guarde uma passagem, indique compasso ou letra de ensaio, parte e objetivo. Defina tempos inicial e final e ordene-a no plano.', 'É o músico que define o estado; a aplicação não avalia a execução automaticamente. Um original em falta não é substituído por outro semelhante.'],
      uk: ['Складні місця й план занять', 'Робоча область прив’язує задачу до точної сторінки, ділянки та видання.', 'У відкритих нотах збережіть фрагмент, укажіть такт або репетиційну літеру, партію та мету. Задайте початковий і цільовий темп та місце в плані.', 'Стан визначає музикант; застосунок не оцінює гру автоматично. Відсутній оригінал не замінюється схожими нотами.'],
      fr: ['Passages difficiles et plan de travail', 'L’espace musicien relie une tâche à une page, une zone et une édition précises.', 'Depuis une partition ouverte, gardez un passage avec mesure ou repère, partie et objectif. Fixez les tempos initial et cible puis classez la tâche dans le plan.', 'Vous décidez de l’état ; l’application n’évalue pas automatiquement le jeu. Un original absent n’est pas remplacé par une partition semblable.'],
      pl: ['Trudne fragmenty i plan ćwiczeń', 'Obszar muzyka wiąże zadanie z dokładną stroną, obszarem i wydaniem.', 'Z otwartych nut zapisz fragment, podaj takt lub literę próby, partię i cel. Ustaw tempo początkowe i docelowe oraz kolejność w planie.', 'Samodzielnie zmieniasz stan; aplikacja nie ocenia gry automatycznie. Brakujący oryginał nie jest zastępowany podobnymi nutami.'],
    },
  },
  {
    id: 'input-and-audio', category: 'rehearsal', access: 'pro', text: {
      ru: ['Управление, метроном и аудио', 'Во время занятия можно настроить клавиши или MIDI-команды, запустить метроном и работать с локальным звуком.', 'Проверьте профиль ввода в настройках: MIDI здесь отправляет команды навигации, а не воспроизводит музыку. Метроном работает на переднем плане; обычное касание и системная кнопка «Назад» остаются доступными.', 'Запись запускается только явным нажатием и видна на экране; прерывание её останавливает. Локальное аудио можно слушать, экспортировать и удалить, а аудиометку связать с точным фрагментом нот.'],
      en: ['Controls, metronome and audio', 'For practice you can set keyboard or MIDI commands, run a metronome and work with local audio.', 'Test input profiles in Settings: MIDI sends navigation commands here; it does not play music. The metronome runs in the foreground, while ordinary touch and Android Back remain available.', 'Recording starts only when you press Record and stays visible; interruption stops it. Local audio can be played, exported or deleted, and a cue can point to an exact score passage.'],
      de: ['Steuerung, Metronom und Audio', 'Beim Üben können Sie Tastatur- oder MIDI-Befehle, Metronom und lokales Audio nutzen.', 'Prüfen Sie Eingabeprofile in Einstellungen: MIDI steuert hier die Navigation und spielt keine Musik. Das Metronom läuft im Vordergrund; Berührung und Android-Zurück bleiben nutzbar.', 'Aufnahme startet nur per Knopfdruck und bleibt sichtbar; Unterbrechung stoppt sie. Lokales Audio lässt sich anhören, exportieren oder löschen und mit einer genauen Notenstelle verknüpfen.'],
      it: ['Comandi, metronomo e audio', 'Durante lo studio puoi configurare tastiera o MIDI, usare il metronomo e gestire audio locale.', 'Prova i profili nelle Impostazioni: qui MIDI invia comandi di navigazione, non suona musica. Il metronomo opera in primo piano; tocco e Indietro restano disponibili.', 'La registrazione parte solo su comando visibile e si ferma se interrotta. Puoi ascoltare, esportare o eliminare l’audio e collegare un punto a un passaggio preciso.'],
      es: ['Controles, metrónomo y audio', 'Puedes configurar teclado o MIDI, usar el metrónomo y trabajar con audio local.', 'Prueba los perfiles de entrada en Ajustes: MIDI envía órdenes de navegación, no reproduce música. El metrónomo funciona en primer plano; tocar y Atrás siguen disponibles.', 'La grabación solo empieza al pulsar y se detiene ante una interrupción. Puedes escuchar, exportar o borrar el audio y vincular una marca a un pasaje exacto.'],
      pt: ['Controlos, metrónomo e áudio', 'Pode configurar teclado ou MIDI, usar o metrónomo e trabalhar com áudio local.', 'Teste os perfis em Definições: MIDI envia comandos de navegação, não toca música. O metrónomo funciona em primeiro plano; toque e Voltar continuam disponíveis.', 'A gravação só começa por comando visível e para numa interrupção. Pode ouvir, exportar ou apagar áudio e ligar uma marca a uma passagem exata.'],
      uk: ['Керування, метроном і аудіо', 'На занятті можна налаштувати клавіші чи MIDI, запустити метроном і працювати з локальним звуком.', 'Перевірте профілі введення в налаштуваннях: MIDI тут керує навігацією, а не відтворює музику. Метроном працює на передньому плані; дотик і «Назад» доступні.', 'Запис починається лише після явного натискання й зупиняється при перериванні. Аудіо можна слухати, експортувати, видаляти та пов’язувати міткою з точним фрагментом.'],
      fr: ['Commandes, métronome et audio', 'Vous pouvez régler clavier ou MIDI, utiliser le métronome et gérer l’audio local.', 'Testez les profils dans Réglages : MIDI commande ici la navigation, il ne joue pas de musique. Le métronome fonctionne au premier plan ; toucher et Retour restent possibles.', 'L’enregistrement démarre seulement par action visible et s’arrête en cas d’interruption. Vous pouvez écouter, exporter, supprimer l’audio et lier un repère à un passage précis.'],
      pl: ['Sterowanie, metronom i dźwięk', 'Podczas ćwiczeń ustaw klawiaturę lub MIDI, metronom i lokalne nagrania.', 'Sprawdź profil wejścia w Ustawieniach: MIDI służy tu do nawigacji, nie odtwarza muzyki. Metronom działa na pierwszym planie; dotyk i Wstecz pozostają dostępne.', 'Nagrywanie zaczyna się tylko po widocznym poleceniu i kończy przy przerwaniu. Dźwięk można odsłuchać, wyeksportować lub usunąć oraz powiązać znacznik z dokładnym fragmentem.'],
    },
  },
  {
    id: 'versions-and-exchange', category: 'rehearsal', access: 'pro', text: {
      ru: ['Версии, перенос пометок и обмен', 'Репетиционные снимки сравнивают изменения; перенос между сканами требует проверки человеком.', 'Сохраните контрольную версию разметки и сравните её с другой версией той же редакции. При замене PDF выберите исходник и новый скан, проверьте предложенные соответствия страниц и примите только нужные.', 'Обмен отправляет лишь выбранные пометки и импортирует отдельную проверяемую копию. Бумажные пометки с чистым эталоном требуют ручной проверки; автоматической гарантии совпадения нет.'],
      en: ['Versions, mark transfer and exchange', 'Rehearsal checkpoints compare changes; transferring between scans requires your review.', 'Save a marking checkpoint and compare it with another version of the exact edition. When relinking a PDF, review proposed page matches between old and new scans and accept only those you want.', 'Exchange sends selected marks only and imports a separate reviewed copy. Paper marks with a clean reference still need manual review; automatic matching is not guaranteed.'],
      de: ['Versionen und Austausch von Markierungen', 'Probenstände zeigen Änderungen; die Übertragung zwischen Scans braucht Ihre Prüfung.', 'Speichern und vergleichen Sie Markierungsstände derselben Ausgabe. Bei einem neuen PDF prüfen Sie die vorgeschlagene Seitenzuordnung und übernehmen nur passende Seiten.', 'Austausch enthält nur ausgewählte Markierungen und importiert eine getrennte, geprüfte Kopie. Auch Papiermarkierungen mit sauberer Vorlage müssen manuell geprüft werden.'],
      it: ['Versioni e scambio di annotazioni', 'Le istantanee di prova mostrano le modifiche; il trasferimento fra scansioni richiede controllo.', 'Salva e confronta versioni della stessa edizione. Se cambi PDF, verifica le corrispondenze proposte fra pagine e accetta solo quelle giuste.', 'Lo scambio invia solo i segni scelti e importa una copia separata da verificare. Anche i segni cartacei con un modello pulito richiedono controllo manuale.'],
      es: ['Versiones e intercambio de anotaciones', 'Los puntos de ensayo comparan cambios; transferir entre escaneos exige revisión.', 'Guarda y compara versiones de la misma edición. Al cambiar PDF, revisa las correspondencias de páginas propuestas y acepta solo las correctas.', 'El intercambio envía únicamente las marcas elegidas e importa una copia separada y revisable. Las marcas en papel con referencia limpia también requieren control manual.'],
      pt: ['Versões e troca de anotações', 'Os pontos de ensaio comparam alterações; transferir entre digitalizações exige revisão.', 'Guarde e compare versões da mesma edição. Ao trocar o PDF, reveja as correspondências propostas das páginas e aceite apenas as corretas.', 'A troca envia só marcas escolhidas e importa uma cópia separada para revisão. Marcas em papel com referência limpa também exigem conferência manual.'],
      uk: ['Версії та обмін помітками', 'Репетиційні знімки порівнюють зміни; перенесення між сканами потребує перевірки.', 'Збережіть і порівняйте версії того самого видання. Під час заміни PDF перевірте запропоновану відповідність сторінок і прийміть лише потрібне.', 'Обмін надсилає тільки вибрані помітки й імпортує окрему копію для перевірки. Паперові помітки з чистим зразком також потребують ручного контролю.'],
      fr: ['Versions et échange d’annotations', 'Les jalons de répétition comparent les changements ; le transfert entre scans exige votre contrôle.', 'Enregistrez et comparez deux versions de la même édition. Si le PDF change, vérifiez les correspondances de pages proposées et n’acceptez que les bonnes.', 'L’échange transmet uniquement les marques choisies et importe une copie séparée à vérifier. Les marques sur papier avec référence propre demandent aussi un contrôle manuel.'],
      pl: ['Wersje i wymiana adnotacji', 'Punkty prób porównują zmiany; przenoszenie między skanami wymaga kontroli.', 'Zapisz i porównaj wersje tego samego wydania. Przy zmianie PDF sprawdź sugerowane dopasowania stron i zaakceptuj tylko właściwe.', 'Wymiana wysyła wybrane znaki i importuje osobną kopię do weryfikacji. Znaki z papieru z czystym wzorcem także wymagają ręcznego sprawdzenia.'],
    },
  },
  {
    id: 'concert-pdf', category: 'rehearsal', text: {
      ru: ['Подготовить концертный PDF', 'Экспорт программы создаёт отдельную копию для чтения или печати, но не заменяет полную резервную копию.', 'Выберите сохранённую программу, проверьте зафиксированный порядок, повторы, заметки, формат A4/Letter, целые страницы или подготовленные области и нужные слои пометок.', 'Просмотрите результат перед сохранением. Концертный файл не меняет исходные PDF и не содержит все данные библиотеки.'],
      en: ['Prepare a concert PDF', 'Programme export creates a reading or print copy, not a full backup.', 'Choose a saved programme and review its frozen order, repeats, notes, A4/Letter size, full pages or prepared regions, and selected annotation layers.', 'Preview before saving. The concert file does not modify source PDFs or contain all library data.'],
      de: ['Konzert-PDF vorbereiten', 'Der Programmexport erstellt eine Lese- oder Druckkopie, keine vollständige Sicherung.', 'Prüfen Sie Reihenfolge, Wiederholungen, Notizen, A4/Letter, ganze Seiten oder vorbereitete Bereiche sowie die gewählten Markierungsebenen.', 'Sehen Sie die Vorschau vor dem Speichern an. Die Ausgangs-PDFs bleiben unverändert; die Datei enthält nicht die ganze Bibliothek.'],
      it: ['Preparare un PDF da concerto', 'L’esportazione crea una copia per lettura o stampa, non un backup completo.', 'Controlla ordine, ripetizioni, note, formato A4/Letter, pagine intere o aree preparate e livelli di annotazione scelti.', 'Guarda l’anteprima prima di salvare. I PDF originali non cambiano e il file non contiene tutta la biblioteca.'],
      es: ['Preparar un PDF de concierto', 'La exportación crea una copia de lectura o impresión, no una copia de seguridad completa.', 'Revisa orden, repeticiones, notas, tamaño A4/Letter, páginas completas o regiones preparadas y capas de anotación elegidas.', 'Previsualiza antes de guardar. Los PDF originales no cambian y el archivo no contiene toda la biblioteca.'],
      pt: ['Preparar um PDF de concerto', 'A exportação cria uma cópia para leitura ou impressão, não uma cópia de segurança completa.', 'Reveja ordem, repetições, notas, formato A4/Letter, páginas completas ou regiões preparadas e camadas escolhidas.', 'Pré-visualize antes de guardar. Os PDFs de origem não mudam e o ficheiro não contém toda a biblioteca.'],
      uk: ['Підготувати концертний PDF', 'Експорт програми створює копію для читання чи друку, а не повну резервну копію.', 'Перевірте порядок, повтори, нотатки, формат A4/Letter, цілі сторінки чи підготовлені ділянки та вибрані шари поміток.', 'Перегляньте результат до збереження. Вихідні PDF не змінюються, а файл не містить усієї бібліотеки.'],
      fr: ['Préparer un PDF de concert', 'L’export du programme crée une copie pour lire ou imprimer, pas une sauvegarde complète.', 'Vérifiez l’ordre, les reprises, les notes, le format A4/Letter, les pages entières ou zones préparées et les calques choisis.', 'Prévisualisez avant d’enregistrer. Les PDF sources ne changent pas et le fichier ne contient pas toute la bibliothèque.'],
      pl: ['Przygotuj koncertowy PDF', 'Eksport programu tworzy kopię do czytania lub druku, nie pełną kopię zapasową.', 'Sprawdź kolejność, powtórzenia, notatki, format A4/Letter, całe strony lub przygotowane obszary i wybrane warstwy.', 'Obejrzyj podgląd przed zapisem. Źródłowe PDF nie zmieniają się, a plik nie zawiera całej biblioteki.'],
    },
  },
  {
    id: 'backup-restore', category: 'data', image: 'backup.png', text: {
      ru: ['Сделать и проверить резервную копию', 'Полная ручная копия нужна для переноса и восстановления на другом устройстве.', 'В настройках данных откройте резервное копирование, выберите место через системное окно Android и дождитесь проверки созданного файла. Храните копию отдельно от планшета.', 'При восстановлении выберите архив, посмотрите сводку и подтвердите действие. Локальные автоматические снимки удобны для недавнего отката, но остаются на этом же устройстве и не заменяют экспорт.'],
      en: ['Make and check a backup', 'A complete manual backup supports transfer and recovery on another device.', 'Open backup in data settings, choose a destination through Android and wait for file verification. Keep a copy away from the tablet.', 'For restore, choose the archive, review its summary and confirm. Local scheduled snapshots help with recent recovery, but remain on this device and do not replace an exported backup.'],
      de: ['Sicherung erstellen und prüfen', 'Eine vollständige manuelle Sicherung dient dem Umzug und der Wiederherstellung auf einem anderen Gerät.', 'Öffnen Sie Sicherung in den Dateneinstellungen, wählen Sie über Android einen Speicherort und warten Sie auf die Dateiprüfung. Bewahren Sie eine Kopie außerhalb des Tablets auf.', 'Zur Wiederherstellung wählen Sie das Archiv, prüfen die Übersicht und bestätigen. Lokale Momentaufnahmen bleiben auf diesem Gerät und ersetzen den Export nicht.'],
      it: ['Creare e verificare un backup', 'Il backup manuale completo serve per trasferire e ripristinare su un altro dispositivo.', 'Apri Backup nelle impostazioni dati, scegli la destinazione con Android e attendi la verifica del file. Conserva una copia fuori dal tablet.', 'Per ripristinare scegli l’archivio, controlla il riepilogo e conferma. Le istantanee locali restano sul dispositivo e non sostituiscono il backup esportato.'],
      es: ['Crear y verificar una copia', 'Una copia manual completa permite transferir y recuperar en otro dispositivo.', 'Abre Copia de seguridad en ajustes de datos, elige destino mediante Android y espera la verificación. Guarda una copia fuera de la tableta.', 'Para restaurar, elige el archivo, revisa el resumen y confirma. Las instantáneas locales siguen en el dispositivo y no sustituyen la copia exportada.'],
      pt: ['Criar e verificar uma cópia', 'Uma cópia manual completa permite transferir e recuperar noutro dispositivo.', 'Abra Cópia de segurança nas definições de dados, escolha o destino pelo Android e aguarde a verificação. Guarde uma cópia fora do tablet.', 'Para restaurar escolha o arquivo, reveja o resumo e confirme. As cópias locais ficam neste dispositivo e não substituem a cópia exportada.'],
      uk: ['Створити й перевірити резервну копію', 'Повна ручна копія потрібна для перенесення й відновлення на іншому пристрої.', 'У налаштуваннях даних відкрийте резервне копіювання, виберіть місце через Android і дочекайтеся перевірки файла. Зберігайте копію окремо від планшета.', 'Для відновлення виберіть архів, перегляньте підсумок і підтвердьте. Локальні знімки залишаються на пристрої й не замінюють експорт.'],
      fr: ['Créer et vérifier une sauvegarde', 'Une sauvegarde manuelle complète permet le transfert et la récupération sur un autre appareil.', 'Dans les réglages des données, choisissez la destination via Android et attendez la vérification du fichier. Gardez une copie ailleurs que sur la tablette.', 'Pour restaurer, sélectionnez l’archive, vérifiez le résumé et confirmez. Les instantanés locaux restent sur l’appareil et ne remplacent pas l’export.'],
      pl: ['Utwórz i sprawdź kopię zapasową', 'Pełna ręczna kopia służy do przenoszenia i odzyskiwania na innym urządzeniu.', 'W ustawieniach danych wybierz kopię zapasową i miejsce przez Androida; poczekaj na weryfikację pliku. Zachowaj kopię poza tabletem.', 'Przy przywracaniu wybierz archiwum, sprawdź podsumowanie i potwierdź. Lokalne migawki pozostają na urządzeniu i nie zastępują eksportu.'],
    },
  },
  {
    id: 'originals-recovery', category: 'data', text: {
      ru: ['Экспорт оригиналов и восстановление файла', 'Ваши исходные ноты можно вывести из приложения отдельно от резервной копии.', 'Выберите ноты и команду экспорта оригиналов, укажите папку через Android и дождитесь проверки каждой копии. При частичной ошибке проверьте папку до повторного запуска.', 'Если старый внешний файл пропал, откройте сведения о недоступном документе и используйте управляемое восстановление или привязку к точно проверенной копии. Не удаляйте единственный оригинал, пока восстановление не завершено.'],
      en: ['Export originals and recover a file', 'You can take your original scores out of the app separately from a backup.', 'Select scores, choose Export originals, pick an Android folder and wait for each copy to be checked. If an export partly fails, inspect the destination before retrying.', 'For a missing older external file, use the document’s recovery or relink action with a verified exact copy. Keep your only original until recovery is complete.'],
      de: ['Originale exportieren und Datei retten', 'Originalnoten können Sie getrennt von der Sicherung aus der App kopieren.', 'Wählen Sie Noten und Originale exportieren, bestimmen Sie einen Ordner und warten Sie auf die Prüfung jeder Kopie. Bei Teilfehlern prüfen Sie den Zielordner vor einem neuen Versuch.', 'Für eine fehlende ältere externe Datei nutzen Sie Wiederherstellung oder Verknüpfung mit einer geprüften genauen Kopie. Löschen Sie das einzige Original nicht vor Abschluss.'],
      it: ['Esportare originali e recuperare file', 'Puoi estrarre gli spartiti originali separatamente dal backup.', 'Seleziona gli spartiti, Esporta originali, la cartella Android e attendi la verifica di ogni copia. Se l’esportazione fallisce in parte controlla la cartella prima di riprovare.', 'Per un vecchio file esterno mancante usa recupero o ricollegamento con una copia esatta verificata. Non eliminare l’unico originale finché il recupero non è finito.'],
      es: ['Exportar originales y recuperar archivos', 'Puedes sacar tus partituras originales aparte de la copia de seguridad.', 'Selecciona partituras, Exportar originales y una carpeta Android; espera la verificación de cada copia. Si falla una parte, revisa la carpeta antes de repetir.', 'Para un archivo externo antiguo que falta, usa recuperación o revinculación con una copia exacta verificada. Conserva el único original hasta terminar.'],
      pt: ['Exportar originais e recuperar ficheiros', 'Pode retirar as partituras originais separadamente da cópia de segurança.', 'Selecione partituras, Exportar originais e uma pasta Android; aguarde a verificação de cada cópia. Se houver falha parcial, confira a pasta antes de repetir.', 'Para um ficheiro externo antigo em falta, use recuperação ou religação com uma cópia exata verificada. Mantenha o único original até concluir.'],
      uk: ['Експорт оригіналів і відновлення файла', 'Оригінальні ноти можна вивести із застосунку окремо від резервної копії.', 'Виберіть ноти, експорт оригіналів і папку Android; дочекайтеся перевірки кожної копії. За часткової помилки перевірте папку перед повтором.', 'Для відсутнього старого зовнішнього файла використовуйте відновлення або прив’язку до перевіреної точної копії. Не видаляйте єдиний оригінал до завершення.'],
      fr: ['Exporter les originaux et récupérer un fichier', 'Vous pouvez extraire vos partitions originales indépendamment d’une sauvegarde.', 'Sélectionnez les partitions, Exporter les originaux et un dossier Android ; attendez la vérification de chaque copie. En cas d’échec partiel, contrôlez le dossier avant de recommencer.', 'Pour un ancien fichier externe manquant, utilisez récupération ou réassociation avec une copie exacte vérifiée. Gardez votre seul original jusqu’à la fin.'],
      pl: ['Eksport oryginałów i odzyskanie pliku', 'Oryginalne nuty można wyprowadzić z aplikacji niezależnie od kopii zapasowej.', 'Wybierz nuty, Eksport oryginałów i folder Androida; poczekaj na sprawdzenie każdej kopii. Przy częściowym błędzie obejrzyj folder przed ponowieniem.', 'Dla brakującego starego pliku użyj odzyskiwania lub powiązania z dokładną zweryfikowaną kopią. Nie usuwaj jedynego oryginału przed końcem.'],
    },
  },
  {
    id: 'earlier-searches', category: 'settings', text: {
      ru: ['Старые поисковые запросы', 'Запросы из ранних версий хранятся отдельно, потому что нельзя надёжно определить, искали ли вы ноты в библиотеке или в интернете.', 'Откройте «Настройки» → «Старые запросы», чтобы просмотреть этот список. Нажатие на запись здесь не запускает поиск у внешнего источника.', 'Если список больше не нужен, нажмите «Очистить» и подтвердите удаление. Эта операция удаляет только старые запросы: ноты, файлы и современный поиск по библиотеке остаются на месте.'],
      en: ['Earlier search queries', 'Queries from older versions are kept separately because their local or online destination cannot be identified reliably.', 'Open Settings → Earlier search history to inspect the list. Selecting an entry here does not send it to an online source.', 'If you no longer need the list, choose Clear and confirm. This removes those earlier queries only; your scores, files and current library search remain intact.'],
      de: ['Frühere Suchanfragen', 'Anfragen aus älteren Versionen bleiben getrennt, da ihr lokales oder Online-Ziel nicht sicher erkennbar ist.', 'Öffnen Sie Einstellungen → Frühere Suchanfragen und sehen Sie die Liste an. Ein Eintrag startet hier keine Suche bei einer externen Quelle.', 'Falls Sie die Liste nicht brauchen, wählen Sie Löschen und bestätigen. Nur diese alten Anfragen werden entfernt; Noten, Dateien und die heutige Bibliothekssuche bleiben erhalten.'],
      it: ['Ricerche precedenti', 'Le ricerche delle vecchie versioni restano separate: non si può stabilire con certezza se fossero locali o online.', 'Apri Impostazioni → Cronologia delle ricerche precedenti per vedere l’elenco. Un elemento qui non invia una ricerca a una fonte esterna.', 'Se l’elenco non serve più, scegli Cancella e conferma. Si eliminano solo quelle ricerche, non gli spartiti, i file o la ricerca attuale nella biblioteca.'],
      es: ['Búsquedas anteriores', 'Las consultas de versiones anteriores se conservan aparte porque no se puede saber con seguridad si eran locales o en línea.', 'Abre Ajustes → Historial de búsquedas anteriores para ver la lista. Elegir una entrada aquí no inicia una búsqueda externa.', 'Si ya no la necesitas, pulsa Borrar y confirma. Solo se eliminan esas consultas; tus partituras, archivos y la búsqueda actual en la biblioteca permanecen.'],
      pt: ['Pesquisas anteriores', 'As pesquisas de versões antigas ficam separadas porque não se consegue saber com segurança se eram locais ou online.', 'Abra Definições → Histórico de pesquisas anteriores para ver a lista. Selecionar um item aqui não inicia uma pesquisa numa fonte externa.', 'Se já não precisar da lista, escolha Limpar e confirme. Só essas pesquisas são removidas; partituras, ficheiros e a pesquisa atual da biblioteca permanecem.'],
      uk: ['Старі пошукові запити', 'Запити з попередніх версій зберігаються окремо: невідомо, чи призначалися вони для бібліотеки, чи для інтернету.', 'Відкрийте «Налаштування» → «Історія старих запитів», щоб переглянути список. Вибір запису тут не надсилає запит зовнішньому джерелу.', 'Якщо список більше не потрібен, натисніть «Очистити» й підтвердьте. Видаляються тільки ці запити; ноти, файли та нинішній пошук бібліотеки залишаються.'],
      fr: ['Anciennes recherches', 'Les requêtes des anciennes versions restent à part : leur destination locale ou en ligne ne peut être établie avec certitude.', 'Ouvrez Réglages → Historique des anciennes recherches pour voir la liste. Choisir une entrée ici ne lance aucune recherche externe.', 'Si la liste ne sert plus, choisissez Effacer et confirmez. Seules ces requêtes disparaissent ; partitions, fichiers et recherche actuelle restent en place.'],
      pl: ['Dawne zapytania', 'Zapytania ze starszych wersji są oddzielne, bo nie wiadomo na pewno, czy dotyczyły biblioteki, czy internetu.', 'Otwórz Ustawienia → Historia dawnych wyszukiwań, aby obejrzeć listę. Wybranie wpisu nie wysyła zapytania do zewnętrznego źródła.', 'Jeśli lista jest zbędna, wybierz Wyczyść i potwierdź. Znikną tylko dawne zapytania; nuty, pliki i obecne wyszukiwanie biblioteki pozostaną.'],
    },
  },
  {
    id: 'settings-and-account', category: 'settings', image: 'settings.png', text: {
      ru: ['Язык, тема, помощь и аккаунт', 'Библиотека работает без аккаунта. Язык и оформление меняются независимо от самих нот.', 'В настройках выберите один из девяти языков или язык устройства, системную/светлую/тёмную тему. Там же находятся сведения о версии, помощь, политика конфиденциальности, права и источники.', 'Приглашённый участник пилота может открыть «Аккаунт», подтвердить адрес кодом и посмотреть срок подписанного офлайн-доступа. Публичной регистрации или магазинной покупки пока нет; удаление аккаунта не удаляет локальные ноты.'],
      en: ['Language, theme, help and account', 'The library works without an account. Language and appearance do not change your scores.', 'In Settings choose one of nine languages or the device language, plus system, light or dark theme. You can also open version details, help, privacy, rights and sources.', 'Invited pilot users may confirm an email code in Account and view their signed offline access expiry. Public registration and store purchase are unavailable; account deletion does not delete local scores.'],
      de: ['Sprache, Design, Hilfe und Konto', 'Die Bibliothek funktioniert ohne Konto. Sprache und Design ändern Ihre Noten nicht.', 'Wählen Sie in Einstellungen eine von neun Sprachen oder die Gerätesprache sowie System-, helles oder dunkles Design. Dort finden Sie Version, Hilfe, Datenschutz, Rechte und Quellen.', 'Eingeladene Tester können im Konto einen E-Mail-Code bestätigen und die Offline-Laufzeit sehen. Öffentliche Registrierung und Store-Kauf gibt es noch nicht; Kontolöschung entfernt keine lokalen Noten.'],
      it: ['Lingua, tema, aiuto e account', 'La biblioteca funziona senza account. Lingua e aspetto non cambiano gli spartiti.', 'Nelle Impostazioni scegli una delle nove lingue o quella del dispositivo e il tema sistema, chiaro o scuro. Trovi anche versione, aiuto, privacy, diritti e fonti.', 'Gli invitati al test possono confermare un codice email e vedere la scadenza offline nell’Account. Registrazione pubblica e acquisti non sono disponibili; eliminare l’account non elimina gli spartiti locali.'],
      es: ['Idioma, tema, ayuda y cuenta', 'La biblioteca funciona sin cuenta. Idioma y aspecto no cambian las partituras.', 'En Ajustes elige uno de nueve idiomas o el del dispositivo y tema del sistema, claro u oscuro. También encontrarás versión, ayuda, privacidad, derechos y fuentes.', 'Los invitados a la prueba pueden confirmar un código por correo y ver la caducidad del acceso sin conexión. No hay registro ni compra pública; borrar la cuenta no borra partituras locales.'],
      pt: ['Idioma, tema, ajuda e conta', 'A biblioteca funciona sem conta. Idioma e aparência não alteram as partituras.', 'Em Definições escolha um dos nove idiomas ou o do dispositivo e tema do sistema, claro ou escuro. Também encontra versão, ajuda, privacidade, direitos e fontes.', 'Convidados do teste podem confirmar um código por email e ver a validade do acesso offline. Não há registo nem compra pública; apagar a conta não apaga partituras locais.'],
      uk: ['Мова, тема, допомога й акаунт', 'Бібліотека працює без акаунта. Мова й оформлення не змінюють нот.', 'У налаштуваннях виберіть одну з дев’яти мов або мову пристрою, системну, світлу чи темну тему. Там є версія, допомога, приватність, права та джерела.', 'Запрошені учасники можуть підтвердити email кодом і побачити термін офлайн-доступу. Публічної реєстрації чи купівлі немає; видалення акаунта не видаляє локальні ноти.'],
      fr: ['Langue, thème, aide et compte', 'La bibliothèque fonctionne sans compte. Langue et apparence ne modifient pas les partitions.', 'Dans Réglages, choisissez parmi neuf langues ou celle de l’appareil et le thème système, clair ou sombre. Vous y trouverez version, aide, confidentialité, droits et sources.', 'Les invités du test peuvent confirmer leur adresse par code et voir la fin de l’accès hors ligne. Inscription et achat publics sont indisponibles ; supprimer le compte ne supprime pas les partitions locales.'],
      pl: ['Język, motyw, pomoc i konto', 'Biblioteka działa bez konta. Język i wygląd nie zmieniają nut.', 'W Ustawieniach wybierz jeden z dziewięciu języków lub język urządzenia oraz motyw systemowy, jasny lub ciemny. Są tam też wersja, pomoc, prywatność, prawa i źródła.', 'Zaproszeni testerzy mogą potwierdzić e-mail kodem i sprawdzić koniec dostępu offline. Nie ma publicznej rejestracji ani zakupu; usunięcie konta nie usuwa lokalnych nut.'],
    },
  },
  {
    id: 'pro-and-owned-data', category: 'settings', access: 'pilot', text: {
      ru: ['Что означает Pro в закрытом пилоте', 'Экран возможностей Pro показывает расширенные действия, но публичной покупки пока нет.', 'Открывайте объяснение Pro из нужного действия или раздела настроек. Для приглашённых участников доступ выдаёт владелец; срок подтверждённого офлайн-права показан в аккаунте. Экран предложения не запускает покупку.', 'Окончание доступа ограничивает создание новых Pro-данных, но не скрывает ноты, пометки, программы и записи, которые уже сохранены. Их чтение, экспорт, удаление и восстановление остаются доступны.'],
      en: ['What Pro means in the closed pilot', 'The Pro catalogue explains advanced actions; public purchase is unavailable.', 'Open the Pro explanation from a relevant action or Settings. Invited participants receive access from the owner, and the signed offline expiry is shown in Account. An offer screen does not start a purchase.', 'Expiry can limit creation of new Pro data, but does not hide saved scores, marks, programmes or recordings. Reading, export, deletion and recovery remain available.'],
      de: ['Pro im geschlossenen Test', 'Der Pro-Katalog erklärt erweiterte Aktionen; ein öffentlicher Kauf ist nicht möglich.', 'Öffnen Sie die Erklärung bei einer passenden Aktion oder in Einstellungen. Eingeladene erhalten Zugang vom Betreiber; das signierte Offline-Ende steht im Konto. Die Angebotsseite startet keinen Kauf.', 'Nach Ablauf kann neue Pro-Erstellung gesperrt sein, nicht aber vorhandene Noten, Markierungen, Programme oder Aufnahmen. Lesen, Export, Löschen und Wiederherstellen bleiben möglich.'],
      it: ['Pro nel test chiuso', 'Il catalogo Pro spiega le funzioni avanzate; non è disponibile un acquisto pubblico.', 'Apri la spiegazione da un’azione pertinente o dalle Impostazioni. Gli invitati ricevono accesso dal proprietario; la scadenza offline firmata appare nell’Account. La schermata non avvia un acquisto.', 'La scadenza può limitare nuove creazioni Pro ma non nasconde spartiti, segni, programmi o registrazioni salvati. Lettura, esportazione, eliminazione e recupero restano possibili.'],
      es: ['Pro en la prueba cerrada', 'El catálogo Pro explica acciones avanzadas; no existe compra pública.', 'Abre la explicación desde una acción o Ajustes. El propietario concede acceso a invitados; la caducidad firmada sin conexión aparece en Cuenta. La pantalla no inicia una compra.', 'La caducidad puede limitar nuevas creaciones Pro, pero no oculta partituras, marcas, programas o grabaciones guardadas. Leer, exportar, borrar y recuperar sigue disponible.'],
      pt: ['Pro no teste fechado', 'O catálogo Pro explica ações avançadas; não existe compra pública.', 'Abra a explicação a partir de uma ação ou das Definições. O proprietário concede acesso a convidados; a validade offline assinada aparece na Conta. O ecrã não inicia uma compra.', 'O fim do acesso pode limitar nova criação Pro, mas não esconde partituras, marcas, programas ou gravações guardadas. Ler, exportar, apagar e recuperar continuam disponíveis.'],
      uk: ['Pro у закритому тесті', 'Каталог Pro пояснює розширені дії; публічної купівлі немає.', 'Відкрийте пояснення з відповідної дії чи налаштувань. Запрошеним доступ надає власник; термін підписаного офлайн-права видно в акаунті. Екран пропозиції не починає купівлю.', 'Після завершення доступу нове створення Pro може обмежуватися, але збережені ноти, помітки, програми й записи не ховаються. Читання, експорт, видалення й відновлення доступні.'],
      fr: ['Pro pendant le test fermé', 'Le catalogue Pro explique les actions avancées ; aucun achat public n’est disponible.', 'Ouvrez l’explication depuis une action ou les Réglages. Le propriétaire donne accès aux invités ; l’échéance hors ligne signée apparaît dans Compte. L’écran d’offre ne lance aucun achat.', 'L’expiration peut limiter la création Pro, mais ne cache pas les partitions, marques, programmes ou enregistrements sauvegardés. Lecture, export, suppression et récupération restent possibles.'],
      pl: ['Pro w testach zamkniętych', 'Katalog Pro objaśnia zaawansowane działania; zakup publiczny jest niedostępny.', 'Otwórz wyjaśnienie przy działaniu lub w Ustawieniach. Zaproszonym dostęp przyznaje właściciel; podpisana data końca offline jest widoczna w Koncie. Ekran oferty nie rozpoczyna zakupu.', 'Wygaśnięcie może ograniczyć tworzenie nowych danych Pro, ale nie ukrywa zapisanych nut, znaków, programów ani nagrań. Czytanie, eksport, usuwanie i odzyskiwanie pozostają dostępne.'],
    },
  },
  {
    id: 'library-health', category: 'library', text: {
      ru: ['Проверить состояние библиотеки', 'Перед работой без сети проверьте доступность нот и коллекций на самом устройстве.', 'Откройте «Настройки» → «Состояние библиотеки» и нажмите «Проверить библиотеку». Дождитесь чисел «Готовы без сети», «Отсутствующие файлы» и «Документы требуют восстановления».', 'Откройте проблемную запись и восстановите точный документ. «Очистить временный кэш» удаляет только подготовленные страницы; эта проверка не меняет внешние оригиналы.'],
      en: ['Check library health', 'Before an offline session, check score and collection availability on this device.', 'Open Settings → Library health and run Check library. Read the counts for offline-ready, missing and damaged documents.', 'Open an affected item and restore its exact document. Clearing temporary page cache does not alter external originals.'],
      de: ['Bibliothekszustand prüfen', 'Prüfen Sie vor einer Sitzung ohne Netz die Verfügbarkeit von Noten und Sammlungen.', 'Öffnen Sie Einstellungen → Bibliothekszustand und starten Sie die Prüfung. Beachten Sie offline bereite, fehlende und beschädigte Dokumente.', 'Öffnen Sie den betroffenen Eintrag und stellen Sie das genaue Dokument wieder her. Der temporäre Seitencache ändert externe Originale nicht.'],
      it: ['Controllare la biblioteca', 'Prima di lavorare offline verifica spartiti e raccolte sul dispositivo.', 'Apri Impostazioni → Stato della biblioteca e avvia il controllo. Leggi i conteggi di documenti pronti, mancanti e danneggiati.', 'Apri la voce interessata e recupera il documento esatto. Svuotare la cache temporanea non cambia gli originali esterni.'],
      es: ['Comprobar la biblioteca', 'Antes de trabajar sin conexión comprueba partituras y colecciones en este dispositivo.', 'Abre Ajustes → Estado de la biblioteca e inicia la comprobación. Revisa los totales disponibles, ausentes y dañados.', 'Abre la entrada afectada y recupera el documento exacto. Vaciar la caché temporal no modifica los originales externos.'],
      pt: ['Verificar a biblioteca', 'Antes de trabalhar offline confirme partituras e coleções neste dispositivo.', 'Abra Definições → Estado da biblioteca e inicie a verificação. Leia as contagens de documentos prontos, em falta e danificados.', 'Abra o item afetado e recupere o documento exato. Limpar a cache temporária não altera os originais externos.'],
      uk: ['Перевірити стан бібліотеки', 'Перед роботою без мережі перевірте доступність нот і колекцій на пристрої.', 'Відкрийте «Налаштування» → «Стан бібліотеки» й запустіть перевірку. Подивіться кількість готових, відсутніх і пошкоджених документів.', 'Відкрийте проблемний запис і відновіть точний документ. Очищення тимчасового кешу не змінює зовнішніх оригіналів.'],
      fr: ['Vérifier la bibliothèque', 'Avant de jouer hors ligne, vérifiez partitions et collections sur cet appareil.', 'Ouvrez Réglages → État de la bibliothèque et lancez le contrôle. Consultez les nombres de documents prêts, absents ou endommagés.', 'Ouvrez la fiche concernée et récupérez le document exact. Vider le cache temporaire ne modifie pas les originaux externes.'],
      pl: ['Sprawdź stan biblioteki', 'Przed pracą offline sprawdź nuty i kolekcje na urządzeniu.', 'Otwórz Ustawienia → Stan biblioteki i uruchom sprawdzanie. Zobacz liczby dokumentów gotowych, brakujących i uszkodzonych.', 'Otwórz problematyczny wpis i odzyskaj dokładny dokument. Czyszczenie pamięci stron nie zmienia zewnętrznych oryginałów.'],
    },
  },
  {
    id: 'practice-history', category: 'library', text: {
      ru: ['История занятий', 'История помогает вернуться к сыгранным нотам; сами файлы и места чтения хранятся отдельно.', 'Откройте «Настройки» → «История занятий». Ищите по названию или композитору среди последних 200 занятий; откройте запись, чтобы вернуться к нотам.', 'Удаление одной записи или очистка истории не удаляет ноты, файлы и место чтения. Перед подтверждением проверьте выбранный диапазон.'],
      en: ['Practice history', 'History helps you return to played scores; the score files and reading position are separate.', 'Open Settings → Practice history. Search titles or composers in the latest 200 sessions and open an entry to return to its score.', 'Removing a session or clearing history does not remove scores, files or reading positions. Check the selected range before confirming.'],
      de: ['Übeverlauf', 'Im Verlauf finden Sie gespielte Noten wieder; Dateien und Leseposition bleiben getrennt.', 'Öffnen Sie Einstellungen → Übeverlauf. Suchen Sie Titel oder Komponisten in den letzten 200 Sitzungen und öffnen Sie einen Eintrag.', 'Das Löschen eines Eintrags oder des Verlaufs entfernt weder Noten noch Dateien oder Lesepositionen. Prüfen Sie die Auswahl vor Bestätigung.'],
      it: ['Cronologia delle sessioni', 'La cronologia ritrova gli spartiti suonati; file e posizione di lettura sono separati.', 'Apri Impostazioni → Cronologia. Cerca titolo o compositore nelle ultime 200 sessioni e apri una voce.', 'Eliminare una sessione o la cronologia non elimina spartiti, file o posizioni. Controlla la selezione prima di confermare.'],
      es: ['Historial de práctica', 'El historial permite volver a partituras tocadas; archivos y posición se guardan aparte.', 'Abre Ajustes → Historial. Busca título o compositor entre las últimas 200 sesiones y abre una entrada.', 'Borrar una sesión o el historial no borra partituras, archivos ni posiciones. Revisa la selección antes de confirmar.'],
      pt: ['Histórico de estudo', 'O histórico ajuda a voltar a partituras tocadas; ficheiros e posição de leitura são separados.', 'Abra Definições → Histórico. Pesquise título ou compositor nas últimas 200 sessões e abra uma entrada.', 'Apagar uma sessão ou o histórico não apaga partituras, ficheiros nem posições. Confira a seleção antes de confirmar.'],
      uk: ['Історія занять', 'Історія допомагає повернутися до зіграних нот; файли й місця читання зберігаються окремо.', 'Відкрийте «Налаштування» → «Історія занять». Шукайте назву чи композитора серед останніх 200 занять і відкрийте запис.', 'Видалення заняття чи очищення історії не видаляє ноти, файли або місця читання. Перевірте вибір перед підтвердженням.'],
      fr: ['Historique de travail', 'L’historique retrouve les partitions jouées ; fichiers et position de lecture restent distincts.', 'Ouvrez Réglages → Historique. Cherchez titre ou compositeur parmi les 200 dernières séances puis ouvrez une entrée.', 'Supprimer une séance ou l’historique ne supprime ni partitions, ni fichiers, ni positions. Vérifiez la sélection avant de confirmer.'],
      pl: ['Historia ćwiczeń', 'Historia pomaga wrócić do granych nut; pliki i miejsca czytania są osobne.', 'Otwórz Ustawienia → Historia ćwiczeń. Szukaj tytułu lub kompozytora w 200 ostatnich sesjach i otwórz wpis.', 'Usunięcie sesji lub historii nie usuwa nut, plików ani miejsc czytania. Sprawdź wybór przed potwierdzeniem.'],
    },
  },
  {
    id: 'input-controls', category: 'rehearsal', access: 'pro', text: {
      ru: ['Клавиши, педали и MIDI', 'Обычные клавиши работают бесплатно. Собственные привязки команд — возможность Pro.', 'В «Настройки» → «Клавиатура, педали и MIDI» выберите команду и нажмите клавишу либо настройте выбранный порт MIDI 1. Конфликтующую привязку сначала удалите.', 'Нажмите «Проверить управление»: счётчик покажет команду без изменения нот. MIDI не воспроизводит музыку; касание экрана и системная «Назад» остаются доступны.'],
      en: ['Keyboard, pedals and MIDI', 'Ordinary keys work in Free. Custom command mapping needs Pro.', 'In Settings → Keyboard, pedals and MIDI choose a command and press a key, or select a MIDI 1 port. Remove a conflicting mapping first.', 'Run Test controls to count commands without changing a score. MIDI does not play music here; touch and Android Back remain available.'],
      de: ['Tastatur, Pedale und MIDI', 'Normale Tasten funktionieren kostenlos; eigene Befehlszuordnung braucht Pro.', 'Wählen Sie unter Einstellungen → Tastatur, Pedale und MIDI einen Befehl und drücken Sie eine Taste oder wählen Sie einen MIDI-1-Port. Entfernen Sie widersprüchliche Zuordnungen.', 'Testen Sie die Steuerung ohne Notenänderung. MIDI spielt hier keine Musik; Berührung und Android-Zurück bleiben verfügbar.'],
      it: ['Tastiera, pedali e MIDI', 'I tasti ordinari funzionano gratis; le assegnazioni personalizzate richiedono Pro.', 'In Impostazioni → Tastiera, pedali e MIDI scegli un comando e premi un tasto o seleziona una porta MIDI 1. Rimuovi prima gli assegnamenti in conflitto.', 'Prova i comandi senza cambiare lo spartito. MIDI qui non suona musica; tocco e Indietro restano disponibili.'],
      es: ['Teclado, pedales y MIDI', 'Las teclas normales funcionan gratis; asignar órdenes propias requiere Pro.', 'En Ajustes → Teclado, pedales y MIDI elige una orden y pulsa una tecla o selecciona un puerto MIDI 1. Elimina antes las asignaciones en conflicto.', 'Prueba los controles sin cambiar la partitura. MIDI no reproduce música aquí; tocar y Atrás siguen disponibles.'],
      pt: ['Teclado, pedais e MIDI', 'As teclas comuns funcionam gratuitamente; mapear comandos próprios exige Pro.', 'Em Definições → Teclado, pedais e MIDI escolha um comando e prima uma tecla ou selecione uma porta MIDI 1. Remova primeiro conflitos.', 'Teste os controlos sem alterar a partitura. MIDI não toca música aqui; toque e Voltar continuam disponíveis.'],
      uk: ['Клавіші, педалі та MIDI', 'Звичайні клавіші працюють безкоштовно; власні прив’язки команд потребують Pro.', 'У «Налаштування» → «Клавіатура, педалі та MIDI» виберіть команду й натисніть клавішу або порт MIDI 1. Спершу приберіть конфлікт.', 'Перевірте керування без зміни нот. MIDI тут не відтворює музику; дотик і системна «Назад» лишаються.'],
      fr: ['Clavier, pédales et MIDI', 'Les touches ordinaires sont gratuites ; attribuer ses propres commandes demande Pro.', 'Dans Réglages → Clavier, pédales et MIDI, choisissez une commande puis une touche ou un port MIDI 1. Retirez d’abord toute attribution conflictuelle.', 'Testez les commandes sans modifier la partition. MIDI ne joue pas de musique ici ; toucher et Retour restent possibles.'],
      pl: ['Klawiatura, pedały i MIDI', 'Zwykłe klawisze działają bezpłatnie; własne przypisania wymagają Pro.', 'W Ustawieniach → Klawiatura, pedały i MIDI wybierz polecenie i klawisz albo port MIDI 1. Najpierw usuń konfliktujące przypisanie.', 'Sprawdź sterowanie bez zmiany nut. MIDI nie odtwarza tu muzyki; dotyk i systemowy Wstecz pozostają dostępne.'],
    },
  },
  {
    id: 'rehearsal-audio', category: 'rehearsal', access: 'pro', text: {
      ru: ['Локальная запись репетиции', 'Запись запускается вручную и остаётся на устройстве. Создание и сохранение цикла A–B требуют Pro.', 'Откройте «Аудио репетиций», нажмите «Записать» и разрешите микрофон Android. Запись видна на экране и останавливается при потере фокуса; затем нажмите «Остановить и сохранить» или удалите дубль.', 'Сохранённый звук можно воспроизвести, экспортировать как исходное аудио, удалить или восстановить бесплатно. При прослушивании задайте A и B, если нужен повтор фрагмента.'],
      en: ['Record a local rehearsal', 'Recording starts by your action and stays on the device. Creating and saving an A–B loop needs Pro.', 'Open Rehearsal audio, press Record and grant Android microphone access. Recording stays visible and stops if the screen loses focus; then Stop and save or discard the take.', 'Saved audio remains playable, exportable, deletable and recoverable in Free. During playback set A and B to repeat a passage if needed.'],
      de: ['Probe lokal aufnehmen', 'Die Aufnahme startet bewusst und bleibt auf dem Gerät. Neue A–B-Schleifen brauchen Pro.', 'Öffnen Sie Proben-Audio, drücken Sie Aufnehmen und erlauben Sie das Mikrofon. Die sichtbare Aufnahme stoppt bei Fokusverlust; speichern oder verwerfen Sie den Durchgang.', 'Gespeichertes Audio bleibt kostenlos abspielbar, exportierbar, löschbar und wiederherstellbar. Für Wiederholung setzen Sie beim Abspielen A und B.'],
      it: ['Registrare una prova in locale', 'La registrazione parte su comando e resta sul dispositivo. Creare un ciclo A–B richiede Pro.', 'Apri Audio delle prove, premi Registra e consenti il microfono Android. La registrazione visibile si ferma se la schermata perde il fuoco; salva o scarta la prova.', 'L’audio salvato si può ascoltare, esportare, eliminare e recuperare gratis. Durante l’ascolto imposta A e B per ripetere un tratto.'],
      es: ['Grabar un ensayo local', 'La grabación empieza cuando lo indicas y queda en el dispositivo. Crear un bucle A–B requiere Pro.', 'Abre Audio de ensayo, pulsa Grabar y permite el micrófono. La grabación visible se detiene si la pantalla pierde el foco; guarda o descarta la toma.', 'El audio guardado puede reproducirse, exportarse, borrarse y recuperarse gratis. Durante la escucha marca A y B para repetir.'],
      pt: ['Gravar um ensaio local', 'A gravação começa por comando explícito e fica no dispositivo. Criar um ciclo A–B exige Pro.', 'Abra Áudio de ensaio, prima Gravar e permita o microfone. A gravação visível para se o ecrã perder foco; guarde ou descarte a tomada.', 'Áudio guardado pode ser ouvido, exportado, apagado e recuperado gratuitamente. Na reprodução marque A e B para repetir.'],
      uk: ['Локально записати репетицію', 'Запис починається лише за вашою дією й лишається на пристрої. Створення циклу A–B потребує Pro.', 'Відкрийте аудіо репетицій, натисніть «Записати» й дозвольте мікрофон. Видимий запис зупиняється при втраті фокусу; збережіть або відкиньте дубль.', 'Збережене аудіо можна слухати, експортувати, видаляти й відновлювати безкоштовно. Під час прослуховування задайте A і B для повтору.'],
      fr: ['Enregistrer une répétition locale', 'L’enregistrement démarre sur demande et reste sur l’appareil. Créer une boucle A–B demande Pro.', 'Ouvrez Audio de répétition, appuyez sur Enregistrer et autorisez le micro. L’enregistrement visible s’arrête si l’écran perd le focus ; gardez ou jetez la prise.', 'L’audio conservé reste lisible, exportable, supprimable et récupérable gratuitement. Pendant l’écoute, marquez A et B pour répéter.'],
      pl: ['Nagraj próbę lokalnie', 'Nagranie zaczyna się świadomie i zostaje na urządzeniu. Tworzenie pętli A–B wymaga Pro.', 'Otwórz Audio prób, naciśnij Nagraj i zezwól na mikrofon. Widoczne nagranie zatrzyma się po utracie fokusu; zapisz lub odrzuć próbę.', 'Zapisane audio można odtwarzać, eksportować, usuwać i odzyskiwać bezpłatnie. Podczas słuchania ustaw A i B do powtórki.'],
    },
  },
  {
    id: 'online-privacy', category: 'settings', text: {
      ru: ['Онлайн-поиск и конфиденциальность', 'Интернет-поиск — отдельная команда раздела «Добавить»; поиск по своей библиотеке работает локально.', 'Перед онлайн-поиском откройте «Настройки» → «Онлайн-поиск и конфиденциальность». Прочитайте перечень источников и решите, отправлять ли им запрос и IP-адрес.', 'Можно отменить действие и пользоваться локальной библиотекой. Сведения о файлах нот не нужны для онлайн-поиска и не отправляются вместе с запросом.'],
      en: ['Online search and privacy', 'Searching sources under Add is separate from local library search.', 'Before online search open Settings → Online search and privacy. Read the source list and decide whether to send a query and IP address to those services.', 'You may cancel and continue using the local library. Score file contents are not part of the search query.'],
      de: ['Online-Suche und Datenschutz', 'Quellensuche unter Hinzufügen ist von der lokalen Bibliothekssuche getrennt.', 'Öffnen Sie zuvor Einstellungen → Online-Suche und Datenschutz. Prüfen Sie die Quellen und entscheiden Sie über Suchanfrage und IP-Adresse.', 'Sie können abbrechen und die lokale Bibliothek weiter nutzen. Notendateien gehören nicht zur Anfrage.'],
      it: ['Ricerca online e privacy', 'La ricerca nelle fonti sotto Aggiungi è separata da quella locale.', 'Prima apri Impostazioni → Ricerca online e privacy. Leggi le fonti e decidi se inviare ricerca e indirizzo IP ai servizi.', 'Puoi annullare e continuare con la biblioteca locale. I file degli spartiti non fanno parte della ricerca.'],
      es: ['Búsqueda en línea y privacidad', 'Buscar fuentes desde Añadir es distinto de buscar en la biblioteca local.', 'Antes abre Ajustes → Búsqueda en línea y privacidad. Lee la lista de fuentes y decide si enviar consulta y dirección IP.', 'Puedes cancelar y seguir con la biblioteca local. Los archivos de partituras no forman parte de la consulta.'],
      pt: ['Pesquisa online e privacidade', 'Pesquisar fontes em Adicionar é separado da pesquisa local.', 'Antes abra Definições → Pesquisa online e privacidade. Veja as fontes e decida se envia consulta e endereço IP.', 'Pode cancelar e continuar com a biblioteca local. Os ficheiros de partituras não fazem parte da consulta.'],
      uk: ['Онлайн-пошук і приватність', 'Пошук джерел у розділі «Додати» відокремлений від локального пошуку бібліотеки.', 'Спершу відкрийте «Налаштування» → «Онлайн-пошук і приватність». Перегляньте джерела й вирішіть, чи надсилати запит та IP-адресу.', 'Можна скасувати дію й користуватися локальною бібліотекою. Файли нот не входять до запиту.'],
      fr: ['Recherche en ligne et confidentialité', 'La recherche de sources dans Ajouter est distincte de la recherche locale.', 'Ouvrez d’abord Réglages → Recherche en ligne et confidentialité. Consultez les sources et décidez de l’envoi de la requête et de l’adresse IP.', 'Vous pouvez annuler et continuer avec la bibliothèque locale. Les fichiers de partitions ne font pas partie de la requête.'],
      pl: ['Wyszukiwanie online i prywatność', 'Szukanie źródeł w Dodaj jest oddzielne od lokalnego wyszukiwania biblioteki.', 'Najpierw otwórz Ustawienia → Wyszukiwanie online i prywatność. Sprawdź źródła i zdecyduj o wysłaniu pytania oraz adresu IP.', 'Możesz anulować i korzystać dalej z biblioteki lokalnej. Pliki nut nie są częścią zapytania.'],
    },
  },
  {
    id: 'local-snapshots', category: 'data', access: 'pro', text: {
      ru: ['Копии на устройстве', 'Проверенные локальные точки удобны для отката. Автоматическое расписание требует Pro; полная ручная копия бесплатна.', 'Откройте «Настройки» → «Резервная копия и перенос» → «Копии на устройстве». Посмотрите последнюю проверенную копию, свободное место и при необходимости нажмите «Создать сейчас».', 'Для возврата сначала выберите «Просмотр перед восстановлением». Сохранённые копии можно смотреть, экспортировать и восстанавливать бесплатно. От потери планшета защищает лишь экспорт в другое место.'],
      en: ['On-device backups', 'Verified local restore points help with recent recovery. Automatic scheduling needs Pro; complete manual backup is Free.', 'Open Settings → Backup and transfer → On-device backups. Check the last verified copy and free space, then use Create now if needed.', 'Use Preview before restore first. Saved copies remain viewable, exportable and restorable in Free. Export elsewhere to protect against device loss.'],
      de: ['Sicherungen auf dem Gerät', 'Geprüfte lokale Punkte helfen beim Zurücksetzen. Automatische Planung braucht Pro; manuelle Vollsicherung ist kostenlos.', 'Öffnen Sie Einstellungen → Sicherung und Übertragung → Sicherungen auf dem Gerät. Prüfen Sie letzte Sicherung und Platz und erstellen Sie bei Bedarf eine.', 'Sehen Sie die Wiederherstellung vorher an. Gespeicherte Kopien bleiben kostenlos prüf-, exportier- und wiederherstellbar. Für Geräteverlust exportieren Sie anderswohin.'],
      it: ['Copie sul dispositivo', 'I punti locali verificati aiutano nel recupero recente. La pianificazione automatica richiede Pro; il backup manuale completo è gratis.', 'Apri Impostazioni → Backup e trasferimento → Copie sul dispositivo. Controlla ultima copia e spazio, poi crea una copia se necessario.', 'Usa l’anteprima prima del ripristino. Le copie salvate restano consultabili, esportabili e recuperabili gratis. Esporta altrove contro la perdita del dispositivo.'],
      es: ['Copias en el dispositivo', 'Los puntos locales verificados ayudan a recuperar cambios recientes. Programar copias requiere Pro; la copia manual completa es gratis.', 'Abre Ajustes → Copia y transferencia → Copias en el dispositivo. Mira la última copia y el espacio; crea una ahora si hace falta.', 'Usa la vista previa antes de restaurar. Las copias guardadas se pueden ver, exportar y restaurar gratis. Exporta fuera ante pérdida del dispositivo.'],
      pt: ['Cópias no dispositivo', 'Pontos locais verificados ajudam na recuperação recente. O agendamento automático exige Pro; a cópia manual completa é grátis.', 'Abra Definições → Cópia e transferência → Cópias no dispositivo. Confira a última cópia e o espaço; crie uma se preciso.', 'Use a pré-visualização antes de repor. Cópias guardadas podem ser vistas, exportadas e repostas gratuitamente. Exporte para outro local contra perda do tablet.'],
      uk: ['Копії на пристрої', 'Перевірені локальні точки допомагають відкотитися. Автоматичний розклад потребує Pro; повна ручна копія безкоштовна.', 'Відкрийте «Налаштування» → «Резервна копія й перенесення» → «Копії на пристрої». Перевірте останню копію й місце, за потреби створіть нову.', 'Перед відновленням перегляньте план. Збережені копії можна переглядати, експортувати й відновлювати безкоштовно. Для захисту від втрати пристрою експортуйте назовні.'],
      fr: ['Sauvegardes sur l’appareil', 'Les points locaux vérifiés aident à revenir en arrière. La planification demande Pro ; la sauvegarde manuelle complète est gratuite.', 'Ouvrez Réglages → Sauvegarde et transfert → Copies sur l’appareil. Vérifiez dernière copie et espace puis créez-en une au besoin.', 'Prévisualisez avant de restaurer. Les copies gardées restent consultables, exportables et récupérables gratuitement. Exportez ailleurs contre la perte de l’appareil.'],
      pl: ['Kopie na urządzeniu', 'Sprawdzone punkty lokalne pomagają odzyskać niedawne dane. Harmonogram wymaga Pro; pełna ręczna kopia jest bezpłatna.', 'Otwórz Ustawienia → Kopia i przenoszenie → Kopie na urządzeniu. Sprawdź ostatnią kopię i miejsce, potem utwórz nową w razie potrzeby.', 'Przed odzyskaniem obejrzyj podgląd. Zapisane kopie można bezpłatnie oglądać, eksportować i przywracać. Na wypadek utraty tabletu wyeksportuj je poza urządzenie.'],
    },
  },
];

export const guideArticles = guideArticlesUnsorted.sort(
  (left, right) => categoryOrder.indexOf(left.category) - categoryOrder.indexOf(right.category),
);

type DetailedArticleId =
  | 'first-scores' | 'import-review' | 'find-in-library' | 'score-details'
  | 'collections-and-batch' | 'reader' | 'programmes' | 'backup-restore'
  | 'originals-recovery' | 'settings-and-account';

