export function articleSteps(article: GuideArticle, locale: Locale): string[] {
  const base = article.text[locale];
  const middle = detailedSteps[article.id as DetailedArticleId]?.[locale];
  return middle ? [base[2], ...middle, base[3]] : base.slice(2);
}
